programs.sol:
"""Detect unusual glyphs, typography, and chat/control boundaries.

Ordinary ASCII and longer native-script pieces are close to zero. Accented
Latin, mathematical symbols, and other marked typography are negative;
word-piece length dilutes this response. Split UTF-8 characters get separate
start/completion estimates. Carry holds only an unfinished character's bytes
and its document label, and is reset at document boundaries.
"""
import unicodedata as ud
from functools import lru_cache
import unihan

READS = ()
MARKERS = {
    '<think>': -4.0,
    '</think>': -4.5,
    '<tool_call>': -3.7,
    '</tool_call>': -1.0,
    '<tool_response>': -2.35,
    '</tool_response>': -4.4,
}


@lru_cache(maxsize=8192)
def character_score(text):
    s = text.strip(' \n\r\t')
    if not s:
        return 0.0
    if s in MARKERS:
        return MARKERS[s]
    if '\x00' in s:
        return -4.7
    if s.isascii():
        if text in ("'", "'t"):
            return -0.4
        if text in ("'s", "'re", "'ve", "'ll", "'d", "'m"):
            return -0.12
        if s.startswith('\\x'):
            return -0.8
        return -0.5 if '\t' in text and len(s) > 1 else 0.0
    length = len(s)
    accents = sum(ord(c) > 127 for c in s)
    score = 0.0
    for c in s:
        if ord(c) < 128:
            continue
        name, cat = ud.name(c, ''), ud.category(c)
        if c == '\ufffd':
            x = -0.45 if text.startswith(' ') else -1.05
        elif name.startswith('LATIN'):
            x = -2.0 - 0.5 * c.isupper()
            if any(mark in name for mark in ('CIRCUMFLEX', 'MACRON',
                                             'LIGATURE', 'LONG S')):
                x -= 0.8
            x /= accents**2
            if text.startswith(' ') and length == 1:
                x *= 0.7
        elif name.startswith('CYRILLIC'):
            x = 0.2
            if 'SIGN' in name:
                x = 1.35 if 'HARD' in name else 0.6
            x = -x / length**2
        elif name.startswith(('HIRAGANA', 'KATAKANA')):
            x = (-0.15 - 1.6 * ('SMALL' in name)) / length**2
        elif name.startswith('IDEOGRAPHIC'):
            x = 0.0
        elif name.startswith('CJK'):
            x = (-0.3 if unihan.gb2312_level(c) != 1 else 0.0) / length**2
        elif name.startswith('FULLWIDTH'):
            x = -0.15
        elif name.startswith('ARABIC'):
            x = -1.8 if cat.startswith('M') else -0.3 / length**2
        elif name.startswith('HANGUL'):
            x = -0.3 / length**2
        elif name.startswith('GREEK'):
            x = (-0.95 - 0.7 * ('WITH' in name)) / length**2
        elif name.startswith('THAI'):
            x = (-2.1 if 'SARA' in name else -0.15) / length**1.5
        elif name.startswith('SUPERSCRIPT'):
            x = -1.3
        elif name.startswith('SUBSCRIPT'):
            x = -1.0
        elif name.startswith('VULGAR FRACTION'):
            x = -2.7
        elif 'SINGLE QUOTATION' in name:
            x = -1.55 if not text.startswith(' ') else -0.7
            if length > 1:
                x = -0.8 * length
        elif 'DOUBLE QUOTATION' in name:
            x = -0.65
        elif 'PRIME' in name or 'MIDDLE DOT' in name:
            x = -1.9
        elif 'BULLET' in name:
            x = -0.85
        elif name.startswith(('SECTION', 'PILCROW', 'INVERTED',
                              'MASCULINE', 'FEMININE', 'MODIFIER')):
            x = -2.7
        elif cat == 'Pd':
            x = -2.0 if not text.startswith(' ') else -1.35
        elif cat == 'Sm':
            x = -1.8
        elif cat == 'Sc':
            x = -1.5
        elif c == '\xa0':
            x = -0.9 / length
        elif cat.startswith(('Z', 'C')):
            x = -1.7
        else:
            x = -2.7 if cat.startswith('S') else -0.7
        score += x
    return score / length


def unfinished(data):
    """The at-most-three bytes of a character not yet fully received."""
    for n in range(1, min(3, len(data)) + 1):
        byte = data[-n]
        if byte < 128:
            break
        if byte >= 192:
            width = 2 if byte < 224 else 3 if byte < 240 else 4
            return data[-n:] if n < width else b''
    return b''


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_bytes[-1]
    start = prefix.position == 0 or prefix.document_ids[-2] != doc
    previous = carry[1] if carry is not None and carry[0] == doc else b''
    tail = unfinished(previous + raw)
    text = prefix.token_strings[-1]
    value = character_score(text)
    if raw and 128 <= raw[0] < 192:
        joined = (previous + raw).decode('utf8', 'replace')
        first = joined[0] if joined else '\ufffd'
        name = ud.name(first, '')
        if name.startswith(('CJK', 'HANGUL')):
            value = -0.9
        elif name.startswith('LATIN'):
            value = -3.2
        else:
            value = -0.6
            if first != '\ufffd':
                value = -0.5 + 0.8 * character_score(joined)
    elif tail:
        # Pad the unseen continuation bytes only to identify the Unicode block,
        # not to guess which particular character will follow.
        width = 2 if tail[0] < 224 else 3 if tail[0] < 240 else 4
        approx = (tail + b'\x80' * (width - len(tail))).decode('utf8', 'replace')
        name = ud.name(approx, '') if len(approx) == 1 else ''
        if name.startswith(('CJK', 'HANGUL')):
            value = 0.05
        elif name.startswith('LATIN'):
            value = -1.5
        elif tail.startswith((b'\xe2\x80', b'\xe2\x81')):
            value = -1.5
        else:
            value = -0.75
    if text == '<|im_start|>':
        value = -0.35 if start else -3.17
    elif text == '<|im_end|>':
        before = '' if start else prefix.token_strings[-2]
        value = 0.6 if before.startswith('</tool_') else 1.65
    elif text == '\x00':
        value = -2.0 if not start and prefix.token_strings[-2].isspace() else -4.7
    elif start and text.isascii() and not text.startswith('<'):
        value -= 0.3
    return (doc, tail), float(value)

programs.haiku:
"""Draft 4: three tiers of non-ASCII value by script, chat markers, partial UTF-8 bytes."""
import unicodedata

READS = ()

MARKERS = {"<|im_start|>": -2.7, "<|im_end|>": 1.1, "<|endoftext|>": 0.0}
MARKUP = {"<think>", "</think>", "<tool_call>", "</tool_response>", "<tool_response>"}
STRONG = {"LATIN", "CHECK", "EM", "EN", "LEFT", "RIGHT", "SUPERSCRIPT", "SUBSCRIPT", "NO-BREAK", "BALLOT", "MODIFIER", "BULLET"}
MID = {"GREEK", "THAI"}
QUIET = {"ARABIC", "HIRAGANA", "KATAKANA", "HANGUL", "FULLWIDTH"}
ZERO = {"CJK", "CYRILLIC", "IDEOGRAPHIC"}


def char_value(ch):
    script = unicodedata.name(ch, "").split(" ")[0]
    if script in ZERO:
        return 0.0
    if script in STRONG or (script not in MID and script not in QUIET and unicodedata.category(ch)[0] in "PSN"):
        return -1.3
    if script in MID:
        return -0.9
    if script in QUIET:
        return -0.2
    return -1.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s in MARKERS:
        return carry, MARKERS[s]
    if s in MARKUP or s.startswith("<|"):
        return carry, -3.5
    if "�" in s:
        return carry, -0.8
    if s.isascii() or not s:
        return carry, 0.0
    chars = [ch for ch in s if not ch.isascii()]
    return carry, sum(char_value(ch) for ch in chars) / len(chars)

programs.sol:
"""Approximate the component with short f-related spelling patterns.

The main response is to fry/fried and Fred/Fried fragments, especially when
split across tokens. Secondary rules cover freezing, free- compounds, file
metadata, folding, the heading 'Title:', and Chinese 炸. Everything else is
zero. This is a partial approximation, not a general pronunciation detector.
"""
import re
import unicodedata
from functools import lru_cache

READS = ()


@lru_cache(maxsize=16384)
def letters(text):
    return ''.join(c for c in unicodedata.normalize('NFKD', text).lower()
                   if not unicodedata.combining(c))


def response(raw, previous, tail):
    s, p = letters(raw).strip(), letters(previous)
    joined = bool(raw) and not raw[0].isspace()
    split_f = joined and p.endswith('f')
    word = 'f' + s if split_f else s

    # Fry's spelling-changing inflections, also shared by Germanic names.
    if re.fullmatch(r'fr(?:y(?:ing)?|ie[ds]?)', word):
        if split_f:
            if word.endswith('s'):
                return 7.0
            return 5.5 if word == 'frie' else 10.0
        if word.endswith('s'):
            return 3.5
        return 10.0 if p.strip() in ('deep', 'air') else 6.8
    if s.endswith('fred'):
        return 1.5 if raw[0].isspace() else 3.3
    if word in ('freeze', 'freezes'):
        return 7.5 if split_f else 2.7
    if s in ('frozen', 'freezing'):
        return 1.4

    # Completions of split name stems and closely related f/r fragments.
    if joined:
        if p.endswith('fre'):
            if s.startswith('der'):
                return 3.2
            if s.startswith(('id', 'ind')):
                return 5.5
            if s.startswith(('i', 'ew', 'er')):
                return 1.3
        if p.endswith('fr') and s.startswith(('y', 'ed', 'id')):
            return 3.0
        if split_f:
            if s == 'ri':
                return 4.0
            if s.startswith('rit'):
                return 3.0
            if s == 'r':
                return 1.3
        if p.endswith('ried') and tail.endswith('fried'):
            if s in ('er', 'e', 'en'):
                return 3.7

    # Freehold, free fall, and a split spelling of freeze.
    if p.endswith('free'):
        if s == 'hold' and joined:
            return 8.0
        if s in ('fall', 'falls'):
            return 4.4
        if s == 'ze' and joined:
            return 5.0

    # Smaller file-related, folding, and heading responses.
    if s == 'filing' and p.strip() == 'effective':
        return 5.4
    if s == 'filed':
        return 1.8 if raw.strip()[0].isupper() else 0.7
    if s == 'fold':
        return 3.8 if p.endswith('blind') else 0.8
    if p.endswith('file'):
        metadata = s.lstrip('_')
        if metadata in ('size', 'sizes'):
            return 3.4
        if metadata in ('id', 'ids', 'name', 'names'):
            return 1.0
    if previous == 'Title' and s == ':':
        return 4.1
    if raw == '炸':  # The Chinese verb fry; also means explode.
        return 4.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    raw = prefix.token_strings[-1]
    value = response(raw, previous, tail)
    words = re.findall(r'[a-z]+', tail + letters(raw))
    tail = words[-1][-32:] if words else ''
    return (doc, raw, tail), value

"""Surface-grammar approximation of a multilingual inflection response.

Recent word frequencies estimate the language. Split Romance plural-verb
endings receive a negative value, strengthened when an infinitive can be
reconstructed. Common irregular verbs, Slavic and Arabic endings, and
Germanic -en have simpler rules. Reflexive/relative-clause cues strengthen
Romance predictions; capitalization weakens them. Repeated middle dots
have a separate positive response. Most other tokens stay near zero.
This is not a complete parser: similar-looking word fragments can fool it.
"""
import codecs
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'es', 'fr', 'it', 'pt', 'de', 'nl', 'pl', 'cs', 'sv')
WORDS = re.compile(r'[^\W\d_]+', re.UNICODE)

# Productive third-person plural endings; alternatives reconstruct infinitives.
ENDINGS = {
    'es': (('arían', 'ar'), ('arán', 'ar'), ('erán', 'er'),
           ('irán', 'ir'), ('erían', 'er'), ('irían', 'ir'),
           ('ieron', 'er ir'), ('ieran', 'er ir'), ('iesen', 'er ir'),
           ('aron', 'ar'), ('aban', 'ar'), ('aran', 'ar'), ('asen', 'ar'),
           ('ían', 'er ir'), ('an', 'ar er ir'), ('en', 'ar er ir')),
    'fr': (('aient', 'er ir re'), ('issent', 'ir'), ('èrent', 'er'),
           ('irent', 'ir'), ('ent', 'er ir re')),
    'it': (('eranno', 'are ere'), ('iranno', 'ire'), ('avano', 'are'),
           ('evano', 'ere'), ('ivano', 'ire'),
           ('iscono', 'ire'), ('ano', 'are'), ('ono', 'ere ire')),
    'pt': (('arem', 'ar'), ('erem', 'er'), ('irem', 'ir'),
           ('aram', 'ar'), ('eram', 'er'), ('iram', 'ir'),
           ('avam', 'ar'), ('iam', 'er ir'), ('am', 'ar'),
           ('em', 'ar er ir')),
}
# Irregular, high-frequency plural auxiliaries and verbs.
IRREGULAR = {
    'es': set('son han van dan están tienen pueden deben hacen dicen '
              'sean hayan vayan sepan'.split()),
    'fr': set('sont ont font vont peuvent doivent veulent savent '
              'disent viennent tiennent prennent étaient seront'.split()),
    'it': set('sono hanno fanno vanno danno stanno possono vogliono '
              'devono dicono vengono sanno saranno erano'.split()),
    'pt': set('são estão têm vêm vão hão foram sejam tinham podem '
              'devem fazem dizem sabem querem'.split()),
}

@lru_cache(maxsize=50000)
def frequencies(word):
    return tuple(zipf_frequency(word.lower(), lang) for lang in LANGUAGES)

@lru_cache(maxsize=50000)
def infinitive_strength(word, lang):
    best = 0.0
    for ending, replacements in ENDINGS[lang]:
        if not word.endswith(ending) or len(word) <= len(ending) + 1:
            continue
        stem = word[:-len(ending)]
        stems = [stem]
        if lang == 'es':
            if stem.endswith('c'):
                stems.append(stem[:-1] + 'z')
            if stem.endswith('qu'):
                stems.append(stem[:-2] + 'c')
            if stem.endswith('gu'):
                stems.append(stem[:-1])
        if lang == 'fr' and stem.endswith('ge'):
            stems.append(stem[:-1])
        for base in stems:
            for replacement in replacements.split():
                infinitive = base + replacement
                freq = zipf_frequency(infinitive, lang)
                if freq >= zipf_frequency(infinitive, 'en') - .5:
                    best = max(best, freq)
    return best


# Per language: ending, checked infinitive, split irregular, whole irregular.
VERB_GAINS = {
    'es': (-1.291, -1.614, -1.458, -1.800),
    'fr': (-1.377, -1.607, -0.944, -1.471),
    'it': (-1.853, -1.085, -2.247, -0.959),
    'pt': (0.000, -2.549, -2.223, -0.867),
}
PLURAL_ENDINGS = {
    'es': ('an', 'en', 'án'), 'fr': ('ent', 'ont'),
    'it': ('ano', 'ono', 'anno'), 'pt': ('am', 'em', 'ão'),
}


def step(carry, prefix, upstream):
    raw, doc = prefix.token_bytes[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', b'', (0.0,) * len(LANGUAGES), ())
    _, word, pending, scores, recent = carry
    decoder = codecs.getincrementaldecoder('utf8')('ignore')
    decoder.setstate((pending, 0))
    text = word + decoder.decode(raw)
    pending = decoder.getstate()[0]
    word = ''
    for match in WORDS.finditer(text):
        w = match.group()
        if match.end() == len(text) and (text[-1].isalpha() or pending):
            word = w
        elif len(w) >= 2:
            recent = (*recent[-3:], w.lower())
            fs = frequencies(w)
            peak = max(fs)
            scores = tuple(.9*s + f - peak for s, f in zip(scores, fs))
    carry = (doc, word[-60:], pending, scores, recent)
    capital = bool(word and word[0].isupper())
    word = word.lower()
    token = raw.decode('utf8', errors='ignore').strip().lower()
    split = bool(raw and not chr(raw[0]).isspace() and len(word) > len(token))
    value = .003 if word and token.isalpha() else 0.0
    if token and len(token) > 1 and set(token) == {'·'}:
        value += .651
    if not word:
        return carry, float(value - .001)

    if any('\u0400' <= c <= '\u04ff' for c in word):
        if word.endswith(('ют', 'ят', 'ются', 'ятся', 'ють')):
            value += -1.045 if split else -.195
        if word.endswith(('ут', 'ат', 'утся', 'атся')):
            value += -.171 if split else -.095
    if token.endswith('ون'):
        value -= .671
    if token.endswith('ين'):
        value -= .190

    active_verb = False
    accented = 'áéíóúàèìòùâêîôûãõçñäöüß'
    latin = word.isascii() or any(c in word for c in accented)
    if latin:
        fs = frequencies(word)
        ranks = [s + .2*z for s, z in zip(scores, fs)]
        language = LANGUAGES[max(range(len(ranks)), key=ranks.__getitem__)]
        if max(ranks) - ranks[0] < 1.5:
            language = 'en'
        if language in VERB_GAINS:
            ending_gain, checked_gain, irregular_split, irregular_whole = (
                VERB_GAINS[language])
            if word in IRREGULAR[language]:
                value += irregular_split if split else irregular_whole
                active_verb = True
            else:
                if split and word.endswith(PLURAL_ENDINGS[language]):
                    if language == 'fr':
                        if word.endswith('aient'):
                            value -= 1.795
                            active_verb = True
                        elif not word.endswith('ment'):
                            value += ending_gain
                            active_verb = True
                    elif language == 'pt':
                        if word.endswith(('am', 'em')):
                            value += -.507 if word.endswith('am') else -.473
                            active_verb = True
                    else:
                        value += ending_gain
                        active_verb = True
                strength = infinitive_strength(word, language)
                if strength >= 2.0 and split:
                    value += checked_gain * min(1.0, (strength - 1.5) / 2.0)
                    active_verb = True
        if language in ('de', 'nl', 'sv') and word.endswith('en'):
            value += -.336 if split else -.018
    if active_verb:
        if recent and recent[-1] in {'se', 'si'}:
            value -= .687
        if any(w in {'que', 'qui', 'che', 'quienes'} for w in recent):
            value -= .779
    if capital:
        value *= .35
    return carry, float(value - .001)

"""A shower-centred lexical response with spelling spillover.

Strong triggers are shower and giving verbs bestow/confer. Split stow,
endow, and -ower words also respond; tower and flower have their own
strengths. Chinese bathing/cooling-tower words and Japanese shower/flower
spellings are included. Selected r-endings are positive after w, negative
after Latin v or doubled b. Initial middle-dot or carriage-return runs are
negative. Everything else is zero. Token boundaries and case matter.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous = '' if fresh else carry[1]
    initial = fresh or carry[2]
    token = prefix.token_strings[-1]
    s = token.strip()
    low = s.lower()
    p = previous.lower()
    match = re.search(r'[^\W\d_]+$', previous + token)
    word = match.group()[-40:] if match else ''
    w = word.lower()
    joined = bool(s and s.isalpha() and not token[0].isspace())
    value = 0.0

    if initial and token in ('··', '\r'):
        value = -3.17 if token == '··' else -4.69
    elif low in ('shower', 'showers'):
        value = 13.0 if s[0].isupper() else 8.4
        if low == 'showers' and s[0].islower():
            value = 10.0
    elif joined and re.search(r'shower(s|ed|ing|y)?$', w):
        value = 6.2 if low == 'ing' else 9.0 if low == 'ed' else 12.7
    elif re.search(r'bestow(s|ed|ing)?$', w) and s.isalpha():
        value = 15.5 if joined and low.startswith('ow') else 8.0
    elif re.search(r'confer(s|red|ring)?$', w) and s.isalpha():
        value = 6.2 if low == 'conferred' else 4.0
        if joined:
            value = 7.0 if w.startswith('confer') else 3.0
    elif joined and low in ('ow', 'owed', 'owing', 'ows'):
        if re.search(r'(stow|endow)(s|ed|ing)?$', w):
            value = 6.5
    elif low in ('ower', 'owers'):
        value = 0.0 if p.endswith('p') else 4.0
        if p.endswith('b'):
            value = 7.5
        elif p.endswith('t'):
            value = 8.0
    elif low.startswith('tower'):
        value = 6.0 if p.endswith('cooling') else 2.2
    elif low.startswith('flower'):
        value = 3.8 if joined else 2.3 if s[0].isupper() else 1.0
        if low == 'flowering':
            value = 0.35
    elif joined and p.endswith('w') and low in ('er', 'ers', 'ert', 'els'):
        value = 1.3 if low == 'er' else 2.1 if low == 'ers' else 0.8
        if p.endswith(('blow', 'skew')):
            value = 5.5
    elif joined and p.endswith('v') and low in (
        'r', 're', 'ret', 'ir', 'irt', 'ivor', 'er', 'ers', 'ern'
    ):
        value = -2.5 if s.isupper() and len(s) > 1 else -0.9
    elif joined and p.endswith('b') and low == 'ber':
        value = -1.3
    elif '洗澡' in s:
        value = 4.2
    elif s == '浴' and previous.endswith(('淋', '洗')):
        value = 9.0 if previous.endswith('淋') else 5.8
    elif s == '塔' and previous.endswith(('冷却', '冷水')):
        value = 6.2
    elif s in ('ワ', 'ワー') and previous.endswith(('フラ', 'シャ')):
        value = 4.7 if previous.endswith('フラ') else 9.0

    initial = initial and token in ('··', '\r')
    return (doc, word, initial), value

programs.haiku:
"""Lexical detector for the word "shower" and its close relatives.

The component writes a large positive value when the word being read is "shower"
(or showers/showered/showering): the strongest response in the whole layer's
MLP-down component. Weaker responses come from words that share the "-ow-er"
spelling or the "bestow/confer" meaning family, and from Chinese bathing words.
Everything else is predicted as 0. The word is the run of letters ending at the
current token, so the value appears on the token that completes the word.
"""
import re

SHOWER = {"shower", "showers", "showered", "showering"}
GRANT = {"bestow", "bestowed", "bestowing", "endow", "endowed", "confer", "conferred",
         "conferring", "confers", "stow", "stowed", "dower"}
BOWER = {"bower", "bowers", "blower", "blowers"}
TOWER = {"tower", "towers", "towering", "flower", "flowers", "sunflower", "sunflowers",
         "watchtower", "watchtowers", "wildflower", "wildflowers", "undertow"}

READS = ()


def step(carry, prefix, upstream):
    text = prefix.text_prefixes[prefix.position]
    if text.endswith("淋浴"):
        return None, 10.0
    if text.endswith(("洗澡", "浴", "澡")):
        return None, 3.5
    match = re.search(r"[a-z]+$", text.lower())
    word = match.group(0) if match else ""
    if word in SHOWER:
        return None, 10.0
    if word in GRANT:
        return None, 7.0
    if word in BOWER:
        return None, 6.0
    if word in TOWER:
        return None, 2.5
    return None, 0.0

programs.sol:
"""Approximate a few lexical preposition constructions, not a full grammar.

COME/BRING followed by 'to' or 'into' gives a large negative value;
short intervening objects/directions are allowed.  'When it comes to'
is weaker.  Thanks, greetings, marriage, and 'home to' are positive.
'Of' is positive after kinship and selected home/place words.
A secondary rule is negative on Greek omicron, especially after tau.
Other positions are zero, except 'be' completing 'come to be'.
The only state is a 100-character tail, reset at document boundaries.
"""
import re

READS = ()


def preposition_value(preposition, previous, tail):
    if preposition in ('to', 'into'):
        if preposition == 'to' and re.search(
                r'\bwhen it (?:come|came|comes)\s*$', tail):
            return -3.6
        if preposition == 'to' and re.search(r'\btime has come\s*$', tail):
            return -5.0
        if previous in ('come', 'came', 'comes', 'coming'):
            return -11.5 if preposition == 'to' else -7.5
        if previous in ('bring', 'brings', 'bringing', 'brought'):
            return -5.8 if preposition == 'to' else -3.8
        if previous == 'put':
            return -2.7 if preposition == 'to' else -1.2
        # A short object or direction can separate BRING/COME from TO.
        words = re.findall(r'[a-z]+|[^a-z\s]', tail)[-7:]
        for distance, word in enumerate(reversed(words[:-1]), 2):
            if word in (',', '.', ';', ':', 'to', 'into'):
                break
            if word in ('bring', 'brings', 'brought', 'bringing'):
                if previous not in ('up', 'down', 'out', 'us'):
                    return -3.5 * 0.8 ** (distance - 2)
            if word in ('come', 'came', 'comes', 'coming'):
                if previous in ('it', 'back', 'home', 'soon'):
                    value = -5.0 * 0.65 ** (distance - 2)
                    return value * 0.5 if previous == 'home' else value
        if preposition == 'into':
            if previous in ('take', 'takes', 'taking', 'taken', 'took'):
                return -1.6
            return -0.12
        if re.search(r'\bthank\s+you\s*$', tail):
            return 10.0
        if previous in ('thanks', 'thank-you'):
            return 4.7
        if previous == 'married':
            return 6.5
        if previous in ('goodbye', 'farewell', 'hello', 'birthday'):
            return 4.0
        if previous in ('congratulations', 'congrats'):
            return 6.0
        if previous in ('birth', 'born', 'death'):
            return 2.8
        if previous == 'host' and re.search(
                r'\b(?:play|plays|played|as)\s+host\s*$', tail):
            return 4.8
        if previous == 'back':
            return -0.4
        if previous == 'welcome':
            return -2.5
        if previous in ('return', 'returns', 'returned', 'returning'):
            return -1.0
        if previous in ('move', 'moves', 'moved', 'moving'):
            return -0.65
        if previous == 'home':
            if re.search(r'\b(?:is|are|was|were|be|been|also|formerly)'
                         r'(?:\s+\w+){0,2}\s+home\s*$', tail):
                return 5.8
            return 0.5
        return 0.0
    if preposition == 'of':
        if previous in ('son', 'grandson', 'brother', 'sister', 'niece'):
            return 4.7
        if previous in ('daughter', 'granddaughter', 'youngest'):
            return 6.0
        if previous == 'wife':
            return 3.3
        if previous in ('child', 'children', 'sons', 'daughters', 'father'):
            return 2.0
        if previous == 'mother':
            return 0.7
        if previous == 'home':
            return 3.8
        if previous == 'country':
            return 0.9
        if previous in ('town', 'province', 'island', 'land', 'world'):
            return 1.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if token.lower() in (' to', ' of', ' into'):
        match = re.search(r"([\w'-]+)\s*$", tail)
        previous = match[1] if match else ''
        value = preposition_value(word, previous, tail)
        if token != token.lower():
            value *= 0.5
    elif token in ('ο', 'ό'):
        # A secondary response on Greek omicron, especially following tau.
        if re.search(r'(?:^|\s)στ$', tail):
            value = -6.5
        elif tail.endswith('τ'):
            value = -2.5
        else:
            value = -0.25
    elif token == ' be' and re.search(
            r'\b(?:come|came|comes|coming) to$', tail):
        value = -3.4
    return (doc, (tail + token.lower())[-100:]), value

programs.haiku:
"""Draft 4: 'to'/'into' after verbs of arrival or bringing is strongly negative; 'to' after
thanks/home is positive; 'of' after family and origin nouns is positive."""
READS = ()

ARRIVE = {"came", "come", "coming"}
BRING = {"comes", "brought", "bring", "bringing", "brings", "put", "puts"}
WEAK = {"returned", "return", "returning", "returns", "moved", "rose", "grew", "welcome"}
ATTRIB = {"thanks", "goodbye", "home"}
FAMILY = {"daughter", "son", "wife", "husband", "brother", "sister", "nephew", "father", "children"}
PLACE = {"country", "home", "town", "land", "world", "province"}

def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower()
    prev2 = prefix.token_strings[-3].strip().lower() if len(prefix) > 2 else ""
    if cur == " to":
        if prev in ARRIVE:
            return carry, -12.0
        if prev == "comes":
            return carry, -2.0 if prev2 == "it" else -6.0
        if prev in BRING:
            return carry, -6.0
        if prev in WEAK:
            return carry, -1.5
        if prev in ATTRIB or (prev == "you" and prev2 == "thank"):
            return carry, 4.0
    elif cur == " into":
        if prev in ARRIVE or prev == "comes":
            return carry, -7.0
        if prev in BRING:
            return carry, -2.0
    elif cur == " of":
        if prev in FAMILY:
            return carry, 4.0
        if prev in PLACE:
            return carry, 1.5
    return carry, 0.0

programs.sol:
"""Filesystem-path landmarks, opposed to shell argument punctuation.

Familiar directory names following a slash have large positive responses.
Dashes introducing shell options have large negative responses, especially
for text-filtering utilities. Ordinary text stays near zero. A short text
suffix supplies context and is reset at document boundaries.
"""
import re

READS = ()

ROOTS = {
    'workspace': 3.2, 'home': 3.5, 'Users': 4.0, 'Volumes': 4.3,
    'usr': 2.2, 'opt': 3.2, 'tmp': 1.65, 'root': 1.8,
    'etc': 1.3, 'media': 2.8, 'Applications': 3.5,
}
UTILITIES = set('''cd cat sed grep head tail find ls cp mv rm mkdir chmod chown
curl wget tar git python python3 pip pip3 bash sh echo sort uniq cut awk xargs
make cargo npm npx node php pytest go rg timeout objcopy dd du diff wc docker
rustc gcc clang javac java tsc jest pnpm yarn ffmpeg unzip zip gzip gunzip mvn gradle
apt apt-get brew pacman ssh ssh-keygen ssh-keyscan ssh-copy-id set export'''.split())
SUBCOMMANDS = set('''test build install run restore checkout diff log status
show clean check fmt fix'''.split())


def predict(s, before):
    if s in ROOTS and before.endswith(('/', '\\')):
        v = ROOTS[s]
        if s == 'usr' and before.endswith('#!/'):
            v = 0.55
        if s in ('home', 'Users') and before.endswith(' /'):
            v = 2.8
        return v
    if s == '/to' and before.endswith('/path'):
        return 2.0
    if s == '/workspace':
        return 1.35
    if s == '/local' and before.endswith('usr'):
        return 2.95
    if s == '··':
        return -0.79

    last_match = re.search(r'(?:^|[^\w/.])([A-Za-z][\w+.-]*)\s*$', before)
    last = last_match[1] if last_match else ''
    # Read the current shell segment, not words inside filenames or code.
    logical = re.sub(r'\\(?:\n|\\n)\s*', ' ', before)
    line = re.split(r'\n|\\n|&&|[|;`]', logical)[-1]
    starts = re.findall(r'(?:^|["$>!])\s*(?:sudo\s+|time\s+)?'
                        r'([A-Za-z][\w+.-]*)', line)
    shell = any(w in UTILITIES for w in starts)
    shell = shell or bool(re.match(r'\s*--[a-zA-Z][\w-]*', line))
    if s in (' -', ' --'):
        if before.endswith('--'):
            return -1.2
        if last in ('grep', 'tail', 'curl', 'cp'):
            return -3.95
        if ((last in UTILITIES and (last != 'set' or shell))
                or (last in SUBCOMMANDS and shell)):
            return -3.1
        return -2.4 if shell else -0.04
    if s == ' /':
        if last in UTILITIES or before.endswith(' >'):
            return -1.2
        if shell:
            return -0.65
        if before.endswith(':'):
            return 0.2
        if last == 'of':
            return -0.4
    if s == ':\\' and re.search(r'(?:^|\W)[A-Za-z]$', before):
        return 3.8 if before[-1].isupper() else 0.8
    path = '://' not in before and re.search(r'(?:^|[\s\"\x27`(=])/[\w./-]+$', before)
    if path:
        directory = before.rsplit('/', 1)[-1]
        if s == '/' and directory in ROOTS:
            return 1.0 if directory in ('opt', 'home', 'etc') else 0.4
        if re.fullmatch(r'/[A-Za-z]', s):
            return 0.3
    if s == ' &&' and shell:
        return -0.7 if before.endswith('/testbed') else -0.3
    if s == ' |' and (shell or before.endswith('>&1')):
        return -0.75
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    # Avoid parsing context for ordinary words and punctuation.
    relevant = (s in ROOTS or s in ('··', ':\\')
                or s.startswith(('/', ' -', ' /', ' |', ' &&')))
    value = predict(s, before) if relevant else 0.0
    return (doc, (before + s)[-180:]), value

programs.haiku:
"""Layer-1 MLP component 5513: a 'Unix path vs. shell command' detector.

Positive: the name of a top-level system directory in an absolute file path, the
'workspace' in '/workspace/app', 'usr' in '/usr/lib', 'opt', 'home', 'tmp', 'Users', ...
Negative: command-line options and operators in a shell command, the ' -' of
'cat -n', 'grep -E', 'tail -50', 'pip install -e', and the ' /' of 'cd /testbed'.
Everything else predicts 0.
"""

READS = ()

# Top-level directory names, with their activation right after a slash.
ROOT_DIRS = {
    "workspace": 3.2, "opt": 3.3, "Users": 4.0, "home": 2.9, "media": 2.7,
    "root": 2.0, "usr": 1.9, "tmp": 1.5, "etc": 1.3, "dev": 0.7, "local": 2.8, "lib": 0.7,
}

# Command-line tools whose options (' -x', ' --xyz') are strongly negative.
OPTION_COMMANDS = {
    "cat", "grep", "head", "tail", "sed", "ls", "python", "python3", "pytest", "git",
    "npm", "npx", "yarn", "pip", "cargo", "node", "bash", "sh", "docker", "curl", "wc",
    "mkdir", "rm", "mv", "cp", "chmod", "pidof", "packer", "gcc", "g++", "javac", "mvn",
    "gradle", "ssh", "tsc", "timeout", "xargs", "jest", "lerna", "phpunit", "rustc",
    "diff", "sudo", "apt", "apt-get", "pnpm", "kubectl", "helm", "tar", "wget", "jq",
    "cmake", "dotnet", "poetry", "conda", "brew", "unzip", "sort", "uniq", "clang",
}
# Shell commands that take options more weakly.
WEAK_COMMANDS = {"find", "go", "make", "cd", "awk", "echo", "touch", "chown"}

# Tokens that end one command and start the next.
SEPARATORS = {" &&", " |", " ;", "&&", "|", ";", " `", "`", "\n"}


def _nearest_command(prefix, reach=24):
    """The closest command name before this token, within the same shell command ('' if none)."""
    strings = prefix.token_strings
    doc = prefix.document_ids
    j = len(strings) - 2
    while j >= 0 and j > len(strings) - 2 - reach and doc[j] == doc[-1]:
        if strings[j] in SEPARATORS or "\n" in strings[j]:
            break
        word = strings[j].strip()
        if word in OPTION_COMMANDS or word in WEAK_COMMANDS:
            return word
        j -= 1
    return ""


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in ROOT_DIRS and prev[-1:] in ("/", "\\"):
        return carry, ROOT_DIRS[tok]
    if tok.startswith("/") and tok[1:] in ROOT_DIRS:
        return carry, 0.5 * ROOT_DIRS[tok[1:]]
    if tok in (" -", " --"):
        cmd = _nearest_command(prefix)
        if cmd in OPTION_COMMANDS:
            return carry, -3.5
        if cmd:
            return carry, -1.5
    if tok in (" /", " &&", " |"):
        cmd = _nearest_command(prefix)
        if cmd:
            return carry, {" /": -1.2, " &&": -0.8, " |": -0.6}[tok]
    return carry, 0.0

"""Wikidata-style "subject | relation | value" lines, and a few other field-label spikes."""

READS = ()

def step(carry, prefix, upstream):
    count, doc, prev = carry if carry is not None else (0, None, "")
    if prefix.document_ids[-1] != doc:
        count, prev = 0, ""
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    value = 0.0
    if "\n" in tok:
        count = 0
        if prev == "<tool_call>":
            value = 0.8
    elif tok == " |":
        value = (0.5, 1.1)[count] if count < 2 else 0.0
        count += 1
    elif tok in (" instance", " country"):
        value = 2.1 if count == 1 else 0.6
    return (count, doc, tok), value

programs.sol:
"""Approximate rare formatting and adjective-suffix responses.

A standalone left curly quote is negative outside recent Han text, especially
at a new line. Recent Han characters weaken the response; document starts
reverse its sign. Literal /* openers at document starts are negative, and the
first starred line after /* plus a newline is strongly positive. Subsequent
starred header lines get a smaller positive value.

The fragment "al" is positive after stems ending in "ion", "ment", or "form",
more so for capitalized stems and stems after a parenthesis, backtick or newline.
Other lexical fluctuations are left unexplained.
"""
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, tail, header_comment = 0, '', False
    else:
        _, position, tail, header_comment = carry
    token = prefix.token_strings[-1]
    value = 0.002
    if token == '“':
        if position == 0:
            value = 0.365
        elif regex.search(r'\p{Script=Han}', tail[-32:]):
            value = -0.09 if tail.endswith('\n') else 0.035
        else:
            line_start = tail.endswith(('\n', '\xa0', '\f'))
            value = -0.41 if line_start else -0.26
    elif position == 0 and token == ' “':
        value = 0.35
    if token == 'al':
        stem = regex.search(r'[A-Za-z]+$', tail)
        if stem and stem.group().lower().endswith(('ion', 'ment', 'form')):
            word = stem.group()
            start = stem.start()
            boundary = tail[start - 1:start] if start else '\n'
            prominent = any(c.isupper() for c in word)
            prominent |= boundary in ('(', '`', '\n')
            value = 0.42 if prominent else 0.20
    if position == 0 and token.startswith('/*'):
        header_comment = True
        if token == '/*':
            value = -0.74
        elif token == '/*\n':
            value = -0.097
        elif token == '/*\r\n':
            value = -0.259
    elif header_comment and token.startswith(' *'):
        if position == 1 and tail.endswith('/*\n'):
            value = 0.887
        elif position == 1 and tail.endswith('/*\r\n'):
            value = 0.718
        else:
            value = 0.13
    if '*/' in tail[-1:] + token:
        header_comment = False
    return (doc, position + 1, (tail + token)[-64:], header_comment), value

programs.haiku:
"""layers.1.mlp.down_proj:5515, a weak, mostly token-idiosyncratic component.

Plain-terms summary: this component is near zero on almost every token (typical size
0.04, with no clear concept behind the spread). It is consistently non-zero on a few
token families, and this program predicts those and nothing else:

- code import keywords (`import`, `from`, `#define`): a small positive value;
- runs of dot leaders (`··`, table-of-contents filler): a positive value;
- the opening curly double quote `“` (in prose): a negative value;
- the chat end marker `<|im_end|>`: a small negative value.

Every other token predicts 0. The values are the average activations seen on
training text for these token families.
"""

READS = ()

CODE_IMPORTS = frozenset({"import", "from", "From", "#define"})
DOT_LEADER_VALUE = 0.12
IMPORT_VALUE = 0.10
OPEN_CURLY_QUOTE_VALUE = -0.10
CHAT_END_VALUE = -0.05


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in CODE_IMPORTS:
        value = IMPORT_VALUE
    elif len(token) >= 2 and set(token) == {"·"}:
        value = DOT_LEADER_VALUE
    elif token == "“":
        value = OPEN_CURLY_QUOTE_VALUE
    elif token == "<|im_end|>":
        value = CHAT_END_VALUE
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate a document-start response, strongest on short Han tokens.

Away from the start, use a near-zero baseline. At the start, distinguish
scripts, capitalization, word frequency, and common formatting characters.
Recognize small later responses to import and parameter-documentation markers.
The numbers are averages fitted to training text, not token-ID lookups.
"""
import unicodedata
import regex
from wordfreq import zipf_frequency
import cedict

DECLARATIONS = frozenset("""
    package import using namespace class def function public private
    protected static const var let theorem lemma
""".split())

READS = ()


def start_value(text, raw):
    if text == '\r':
        return -2.3
    if text == '<|endoftext|>':
        return -7.35
    if text == '<|im_start|>':
        return 0.65
    if text == '<|im_end|>':
        return 1.15
    word = text.strip()
    spaced = text.startswith(' ')
    newlines = text.count('\n')
    if not word:
        if text == '\t':
            return -3.43
        if newlines == 1:
            return 0.7 if spaced else 2.35
        if newlines > 1:
            return -1.75 if spaced else -0.4
        return -0.5
    han = regex.findall(r'\p{Script=Han}', word)
    if han:
        if not cedict.glosses(word):
            return 1.3
        return 4.2 if len(han) == 1 else 2.7 if len(han) == 2 else 1.5
    if regex.search(r'[\p{Script=Hiragana}\p{Script=Katakana}]', word):
        return 1.1
    if regex.search(r'\p{Script=Hangul}', word):
        return 1.3
    if word.isdigit():
        return -0.25
    if word in DECLARATIONS:
        return -1.2
    if word.isalpha():
        if spaced:
            return -0.4 if word[0].isupper() else -0.26
        if not regex.fullmatch(r'\p{Script=Latin}+', word):
            return 0.5 if word[0].isupper() else -0.19
        frequency = zipf_frequency(word, 'en')
        if word[0].isupper():
            return max(0.2, min(1.2, 2.4 - 0.35 * frequency))
        return -0.6 if frequency < 2.5 else -0.15
    if '\ufffd' in word:
        return 1.8 if raw and 0xE4 <= raw[0] <= 0xE9 else 0.3
    category = unicodedata.category(word[0])
    if word == '//' and newlines == 1:
        return -4.87  # An otherwise empty line comment.
    if newlines:
        if newlines > 1:
            return -0.3
        return 1.7 if category == 'Ps' else 0.8
    if word == ';':
        return 1.6
    if word in ('!', '?'):
        return 1.0
    if word == '|':
        return 2.0  # Table or pipeline separator.
    if category == 'Ps':
        return 0.36 if spaced else 1.6
    if category == 'Pi':
        return 0.3 if spaced else 2.2
    if category == 'Pe':
        return -0.5
    if category in ('Pd', 'Pc', 'Sk'):
        return -0.4
    return -0.15 if spaced else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry != doc
    text = prefix.token_strings[-1]
    value = 0.001
    if first:
        value = start_value(text, prefix.token_bytes[-1])
    elif text == 'import':
        value = 0.17
    elif text == 'param' and prefix.token_strings[-2].endswith(('@', '<', '</')):
        value = -0.22
    elif text in ('<|im_start|>', '</tool_call>', '</tool_response>'):
        value = -0.07
    return doc, float(value)

"""Approximate large responses to short s-vowel-consonant fragments.

Short sin/syn, sym and sig-like pieces receive negative values, including
when split across tokens. Selected Greek/Cyrillic splits are stronger;
some open-vowel continuations are positive. The Romance 'without'
spellings have separate rules, with language inferred from recent words.
Longer fragments are attenuated; most other positions stay near zero.
This omits small word-specific offsets and finer context effects.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(20000)
def roman(s):
    # Do not turn unrelated Han words into accidental Latin syllables.
    if any(c.isalpha() and ord(c) > 127 and not any(
        k in unicodedata.name(c, '')
        for k in ('LATIN', 'GREEK', 'CYRILLIC', 'ARABIC')) for c in s):
        return s.lower()
    # Preserve sh-sounds and the Russian ts affricate, rather than calling them s.
    # Modern Greek eta has the same vowel sound as iota.
    s = s.translate(str.maketrans({
        'η': 'i', 'ή': 'i', 'Η': 'I', 'Ή': 'I',
        'š': 'sh', 'Š': 'Sh', 'ş': 'sh', 'Ş': 'Sh'}))
    return anyascii(s.replace('ц', '#').replace('Ц', '#')).lower()

@lru_cache(20000)
def language(text):
    words = re.findall(r'[^\W\d_]+', text.lower())[-14:]
    if len(words) < 3:
        return 'en'
    scores = {lang: sum(zipf_frequency(w, lang) for w in words)
              for lang in ('en', 'es', 'pt', 'fr', 'it')}
    best = max(scores, key=scores.get)
    return best if scores[best] - scores['en'] > 0.5 * len(words) else 'en'


def response(previous, token, context):
    word = token.strip().lower()
    new_word = token[:1].isspace() or not context or not context[-1].isalnum()
    if word == 'senza':
        return -6.4
    if word == 'sans':
        return -6.0 if new_word and language(context) == 'fr' else -3.7
    if word == 'sin':
        return -7.0 if new_word and language(context) == 'es' else -2.0
    if word == 'sem':
        return -6.0 if new_word and language(context) == 'pt' else -0.7

    a, b = roman(context[-8:]), roman(token)
    boundary = len(a)
    without = re.search(r'(?<![a-z])s(?:ans|enza)\Z', a + b)
    if without and without.start() < boundary < without.end():
        return -7.5
    joined = a + b
    syllable = re.compile(r's([aeiouy]?)([a-z]?)')
    matches = [syllable.match(joined, i) for i, ch in enumerate(joined)
               if ch == 's']
    matches = [m for m in matches if m.end() > boundary]
    if not matches:
        return -0.001
    m = max(matches, key=lambda m: (bool(m[1]), m[2] in 'nmgl'
                                  and bool(m[2]), m.start()))
    vowel, consonant = m.groups()
    cross = m.start() < boundary
    tail = re.match('[a-z]*', (a + b)[m.end():]).group()
    isolated = cross and bool(re.fullmatch('[^a-z]*s', roman(previous)))
    greek = any('GREEK' in unicodedata.name(c, '') for c in context[-8:] + token)
