        if len(token.strip()) >= 2:
            value = -1.8
    if first and token.strip() and not token.startswith('<|'):
        value -= 0.09

    if any(c in token for c in '.!?\n<>。！？'):
        run = 0
    else:
        run += 1
    return (doc, run, token, (tail + token)[-80:], position + 1), value

"""Coarse token-form and document-start approximation.

Use article, capitalization, script, module-word and decimal-parity averages
at document starts. An initial pair of tokens '1', '2' has a large negative
spike on '2'. Elsewhere stay close to zero, with small spacing, alphabetic,
replacement-character and code-punctuation offsets. Most variation is omitted.
"""
import regex

READS = ()
ARTICLES = {'a', 'an', 'the'}
MODULE_WORDS = {'import', 'package', 'include', 'require', 'using'}
ESCAPES = {'\\n', '\\t', '\\r', '\\\\'}


def at_document_start(text):
    word = text.strip()
    if word.lower() in ARTICLES:
        return 0.235
    if word.isalpha() and word.istitle():
        return 0.091 if word.isupper() else -0.187
    if word.lower() in MODULE_WORDS:
        return 0.268
    if regex.search(r'\p{Script=Han}', word):
        return -0.164
    if word.isdecimal():
        return -0.26 if int(word) % 2 else -0.01
    if regex.search(r'\p{Script=Cyrillic}', word):
        return 0.249
    return -0.015


def later_token(text):
    word = text.strip()
    if text.startswith(' '):
        return -0.017 if '\n' in text else -0.003
    if word.isalpha() and text and not text[0].isspace():
        return 0.0004 if len(word) == 1 else 0.0064
    if '\ufffd' in text:
        return 0.013
    if ']' in text:
        return 0.018
    if word in ESCAPES:
        return 0.020
    return 0.0005


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    position = 0 if first else carry[1] + 1
    if first:
        value = at_document_start(text)
    elif position == 1 and carry[2] == '1' and text == '2':
        value = -1.454
    else:
        value = later_token(text)
    return (doc, position, text), value

"""Numeral-adjacent counters, measurements, and quantity qualifiers.

This is a sparse signed lexicon, not a universal number detector: counting
sheets, texts, sets, people, or organizations tends positive; selected measures,
ranks, ratios, and radix/dimension words tend negative. Most other tokens are
zero. These signed groups summarize training activation patterns.
Separate rules cover small adjective baselines and numerical document starts.
"""
import inflect

READS = ()
_inflector = inflect.engine()
NUMBER_WORDS = {
    _inflector.number_to_words(n).split()[-1]
    for n in list(range(20)) + list(range(20, 100, 10))
    + [100, 1000, 1000000, 1000000000]
}
HAN_NUMERALS = set('零〇一二三四五六七八九十百千万萬亿億两兩几幾多少')

# Surface forms matter: these are selected counters and units, not all nouns.
HAN_UNITS = [
    ('枚篇套', 1.9),                # sheets, written pieces, sets
    ('人家台艘', 1.1),              # people, organizations, machines, ships
    ('名字门門首遍处處', 0.8),       # other counted people, items, occurrences
    ('只節节杯筆', 0.5),
    ('月', 0.33), ('年日', 0.12),   # calendar units
    ('米英', -0.6), ('尺', -1.3), ('秒', -1.0),
    ('块塊', -0.7),                # currency/quantity pieces
    ('维維', -0.8), ('强強', -2.0), # dimensions and tournament ranks
    ('成', -3.0),                  # proportions in tenths
    ('科', -1.8),
]
EASE = {'simple', 'easy', 'quick'}
EXTENT = {'equal', 'long', 'short'}
ENGLISH_UNITS = [
    ({'page', 'pages'}, 0.6), ({'-page'}, 1.1),
    ({'-member'}, 0.65),
    ({'feet'}, -0.65), ({'foot'}, -0.4), ({'-foot'}, -2.4),
    ({'-acre'}, -0.6), ({'degree', 'degrees'}, -0.3),
    ({'-fold', 'fold'}, -0.7), ({'-way', 'ways'}, -0.45),
    ({'-sided'}, -2.0), ({'-run'}, -1.0), ({'-day'}, -0.35),
    ({'time'}, -0.2), ({'million', 'billion', 'thousand'}, -0.14),
    ({'months'}, 0.15), ({'years'}, 0.04),
