        previous, digits, age, first = '', 0, 0, s
    else:
        _, previous, digits, age, first = carry
    word, prevword = s.strip().lower(), previous.strip().lower()
    numeric = (bool(previous) and
               (previous[-1].isdigit() or previous[-1] in HAN_NUMERALS
                or prevword in NUMBER_WORDS))
    value = 0.0
    if word in EASE:
        value = -2.8 if numeric and word == 'simple' else 0.24
    if word in EXTENT:
        value = -0.8 if numeric else 0.14
