    if age == 0 and len(s) == 1 and s.isdecimal():
        value = 0.12 if s == '0' else -0.35
    if age == 1 and first == '1' and s == '2':
        value = -5.347
    if age == 2 and first == '1' and previous == '2' and s == '2':
        value = -2.166
