"""Approximate a detector of openings in multiline code and TeX.

Opening brackets fused with line breaks are positive. Braces are strongest
for imports and object literals, weaker for functions, and near zero for
control flow. The current and previous nonblank lines supply this context.
Python header colons, triple-quote boundaries, Markdown headings after blank
lines, question labels, TeX openings, page breaks, and middle-dot fillers
have separate responses. Ordinary text predicts zero.
"""
import re

READS = ()
CONTROL = re.compile(
    r'(?:^|[;{}])\s*(if|else|for|while|switch|catch|try|do|finally)\b'
)
TYPE = re.compile(r'\b(class|struct|interface|enum|namespace|module)\b')
IMPORT = re.compile(r'\bimport\b')
EMPTY_LINE = re.compile(r'[\s\d|+\-]*')
OPEN_LINE = re.compile(r'[\s()\[\]{}=,:!>]*[({\[][ \t]*(?:\r?\n)+')


def brace_value(header, escaped):
    # Second column: a literal trailing backslash rather than a newline.
    header = EMPTY_LINE.sub('', header, count=1)
    if IMPORT.search(header):
        pair = (1.9, 1.4)
    elif '=>' in header:
        pair = (0.44, 0.66)
    elif CONTROL.search(header):
        pair = (-0.04, 0.25)
    elif TYPE.search(header):
        pair = (0.84, 1.0)
    elif header.rstrip().endswith(')'):
        pair = (0.5, 0.9)
    elif header.rstrip().endswith(('=', ':', ',', '[', '{')):
        pair = (1.0, 0.9)
    else:
        pair = (0.6, 0.75) if header.strip() else (0.0, 0.0)
    return pair[bool(escaped)]


def response(s, line, prior, previous):
    header = line if not EMPTY_LINE.fullmatch(line) else prior
    header = EMPTY_LINE.sub('', header, count=1)
    if s == '###' and not line.strip() and previous.endswith('\n\n'):
        return 0.15
    if re.fullmatch(r'[ \t]*[\"\']{3}(?:\r?\n)+', s):
        return 0.0 if prior.rstrip().endswith(':') else 0.27
    if re.fullmatch(r'[^\w]*:(?:\r?\n)+', s):
        if header.strip() in ('Q', 'Question'):
            return 0.4 if header.strip() == 'Q' else 0.75
        if re.search(r'\bdef\b|\)\s*->', header):
            if s.startswith('()'):
                return 0.28
            return 0.46 if s.startswith(')') else 0.75
        if re.search(r'\bclass\b', header):
            return 0.65
    if s == '{\\':
        return 0.17
    if s.endswith('\\') and s.strip() in ('(\\', '[\\'):
        return 0.15 if '(' in s else (0.53 if s.startswith(' ') else 0.05)
    if OPEN_LINE.fullmatch(s) or re.fullmatch(r'[ \t]*[({\[]\\', s):
        body = s.rstrip('\r\n\\').strip()
        if body.endswith('{'):
            if body.startswith(')'):
                return 0.2
            return brace_value(header, s.endswith('\\'))
        if body.endswith('('):
            if body.startswith('!'):
                return 0.55
            return 1.1 if s.startswith(' ') else 0.91
        return 0.9
    if re.fullmatch(r'\):(?:\r?\n|\\)+', s):
        if re.search(r'\bdef\b', header + ' ' + prior):
            return 0.46
        if TYPE.search(header):
            return 0.65
        return -0.19 if CONTROL.search(header) else -0.04
    if s == ' {' or re.fullmatch(r'[\s(\[=,:"}]+\{', s):
        if IMPORT.search(header):
            return 1.35
        if TYPE.search(header):
            return 0.5
        if CONTROL.search(header):
            return -0.1
        if s == ' {':
            return 0.15
        if '(' in s or '",' in s:
            return 0.53
        return 0.75 if '[' in s else 0.06
    if s == '\\' and previous.rstrip().endswith('{'):
        return 0.19 if '_' in previous else 0.89
    if s == '\x0c':
        return 0.64
    if len(s.strip()) > 1 and set(s.strip()) == {'·'}:
        return -0.42
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, prior, previous = '', '', ''
    else:
        _, line, prior, previous = carry
    s = prefix.token_strings[-1]
    value = response(s, line, prior, previous)
    text = (line + s).replace('\\n', '\n').replace('\\t', '\t')
    parts = text.split('\n')
    for part in parts[:-1]:
        if not EMPTY_LINE.fullmatch(part):
            prior = part[-256:]
    line = parts[-1][-256:]
    if s.startswith('<|'):
        line, prior = '', ''
    return (doc, line, prior, s), value

