"""Block openers: a bracket that ends a line opens a block, and the model's
MLP-1 unit writes a positive signal there, except after control statements (if/for/else...)."""
import re

CONTROL = {"if", "else", "for", "while", "switch", "try", "catch", "do", "with", "elif", "foreach", "unless"}
BRACKET_END = re.compile(r"[\(\[\{][\\]?\s*$")

READS = ()

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc or len(prefix.token_ids) == 1:
        line = ""
    else:
        line = carry[1]
    tok = prefix.token_strings[-1]
    value = 0.0
    if "\n" in tok and BRACKET_END.search(tok):
        head = re.match(r"\s*([A-Za-z]+)", line)
        value = 0.0 if head and head.group(1) in CONTROL else 0.5
    elif tok == " {":
        value = 0.2
    elif tok == "\r":
        value = 0.7
    elif tok == ";":
        value = -0.1
    new_line = line + tok if "\n" not in tok else ""
    return (doc, new_line[-60:]), value

programs.sol:
"""A document-initial pulse, stronger for familiar capitalized English.

The pulse continues while the document consists of repeats of its first token;
otherwise it is zero. Its size is approximated by word familiarity, case,
articles, question words, code/quote openers, numbers and whitespace. These
broad classes deliberately leave token-specific differences unexplained.
"""
from wordfreq import zipf_frequency

READS = ()
QUESTIONS = frozenset('who why when where which whose whom'.split())
DECLARATIONS = frozenset('package import from using def'.split())


def initial_size(text):
    if text == '<|endoftext|>':
        return 15.5
    if text.rstrip() in ('"', '"""', "'''") or text.startswith(('#!', '<?')):
        return 11.5
    word = text.strip()
    if not word:
        if text == '\t':
            return 13.5
        if '\n' in text:
            return 3.0
        return 2.5 if len(text) == 1 else -0.5
    if text.startswith('<|'):
        return 2.0
    if word.isdigit():
        return 7.0

    lower = word.lower()
    title = word.istitle()
    if word in DECLARATIONS and text == word:
        return 11.5
    if lower in ('what', 'how'):
        return 21.5 if title else 12.0
    if lower in QUESTIONS:
        return 9.5 if title else 6.0
    if lower in ('a', 'an'):
        base = 12.0 if len(word) == 1 else 8.0
        return base + (4.0 if title and text == word else 0.0)
    if lower == 'the':
        return 10.0 if title else 7.0

    frequency = zipf_frequency(word, 'en')
    if title:
        if len(word) == 1:
            return 14.0 if frequency >= 5.8 else 9.0
        if frequency >= 5.8:
            return 10.0
        return 7.0 if len(word) <= 3 else 4.2
    if frequency >= 5.8:
        return 6.0
    if text.startswith(' '):
        return 3.8
    return 3.0 if '\n' in text else 4.5


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or document != carry[0]:
        size = initial_size(prefix.token_strings[-1])
        carry = (document, token, size, True)
    else:
        document, first, size, uniform = carry
        uniform = uniform and token == first
        carry = (document, first, size, uniform)
    return carry, carry[2] if carry[3] else 0.0

programs.haiku:
"""Layer-1 MLP down-projection, component 5529: a document-opening detector.

The component is silent inside a document and speaks only at a document's first token.
A document start is position 0 of a row, or the first token after a document break
inside a packed row. There the model's attention sees only that one token, so the
component's size depends only on what that token is, and on how it looks:

* a capitalised sentence opener (I, A, The, How, What, Some, Most, We ...) is large;
* a lowercase or space-led sentence opener (" a", " the", " to") is medium-high;
* a digit is medium-high;
* a short capitalised fragment (A, S, Ar, Mel) is medium;
* other words, punctuation and code are low-medium;
* whitespace and special tokens (<|im_start|>, <|endoftext|>) are lowest.

Everywhere else the component predicts 0.
"""

import re

READS: tuple[str, ...] = ()

# Words that typically open a sentence or title: articles, pronouns, question words,
# quantifiers and possessives. Verbs and prepositions are left out on purpose.
SENTENCE_OPENERS = frozenset(
    """the a an i we you he she it they this that these those what how why when where
    who which some several many most few every each all one no there here my your our
    their his her its two three first new more""".split()
)


def value(token):
    """The component's activation for a token that starts a document."""
    if token.strip() == "" or re.fullmatch(r"<\|.*\|>", token):
        return 2.5
    if re.fullmatch(r" ?\d+", token):
        return 7.0
    m = re.fullmatch(r"( ?)([A-Za-z]+)", token)
    if m is None:
        return 4.3  # punctuation, code, CJK and other symbols
    lead, word = m.group(1), m.group(2)
    if word[0].isupper() and not lead and word.lower() in SENTENCE_OPENERS:
        return 12.0
    if word.lower() in SENTENCE_OPENERS:
        return 7.5
    if word[0].isupper() and len(word) <= 3:
        return 7.0
    return 4.5


def step(carry, prefix, upstream):
    """Called once per token. Predicts the activation at the newest token."""
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return carry, 0.0
    return carry, value(prefix.token_strings[-1])

programs.sol:
"""A small lexical approximation, not a complete activation reconstruction.

Chinese 'almost', 'similar' and 'roughly the same' give large negative
values; emphasis, restrictions and proportions give smaller ones. The
伦/倫 (peer/relations) family is negative, attenuated in foreign names.
English similarity words instead have small positive values; continuation
words are weakly negative. Correctness/trend words and the final particle
囉 are positive; the word for nutrition is negative. Other cues are
repeated middle dots and source-file opening keywords.

Remember the previous token and unfinished UTF-8 bytes, resetting both
at document boundaries. Unrecognized tokens predict zero. Cue estimates are halved: training
interventions favored conservative magnitudes over full lexical estimates.
"""
import codecs
from functools import lru_cache
import opencc

READS = ()
_converter = opencc.OpenCC("t2s")


@lru_cache(maxsize=24000)
def simplify(text):
    return _converter.convert(text)

EMPHASIS = {
    '尤其', '唯一', '专门', '甚至', '甚至是', '最为', '只要是',
    '的确', '格外', '堪称', '简直',
}
# Common foreign-name syllables: 伦 is weaker inside transliterated names.
NAME_SYLLABLES = set('阿艾巴比卡德罗洛劳凯杰索尔加')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    unfinished = b'' if first else carry[2]
    raw = unfinished + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'replace', False)
    unfinished = raw[used:]
    text = simplify(text)
    value = 0.0
    if first and text in {'package', 'import'}:
        value = 1.07 if text == 'package' else 0.82
    elif text == 'import':
        value = -0.14
    elif text.strip().lower() in {'similar', 'nearly', 'hardly', 'virtually'}:
        value = 0.22
    elif text.strip().lower() in {'like', 'unlike', '-like'}:
        value = 0.08
    elif text.strip().lower() in {
        'continue', 'continues', 'continuing', 'continuity', 'relatively',
    }:
        value = -0.14
    elif text == '几乎':
        value = -4.2
    elif text == '几乎所有':
        value = -2.3
    elif text == '类似':
        value = -4.0
    elif text.startswith('类似'):
        value = -2.7
    elif text == '差不多':
        value = -2.3
    elif text == '似':
        if previous.endswith('类'):
            value = -5.1
        elif previous in {'近', '形', '酷', '神'}:
            value = -2.4
        else:
            value = -0.6
    elif text == '像':
        if previous == '很':
            value = -2.7
        elif previous in {'有点'}:
            value = -1.3
        else:
            value = -0.1
    elif text in {'相似', '接近', '疑似', '似的'}:  # likeness / proximity
        value = -0.9
    elif text == '伦':
        if previous in {'乱', '不'}:
            value = -5.3
        elif previous in NAME_SYLLABLES:
            value = -0.8
        else:
            value = -3.4
    elif text == '啰':  # colloquial sentence-final particle 囉
        value = 2.9
    elif text == '伦理':
        value = -2.4
    elif text in {'正确', '正确的', '趋势', '持续'}:  # correct / trend / ongoing
        value = 0.6
    elif text == '营养':
        value = -1.6
    elif text == '例外':
        value = -2.2
    elif text in {'纯', '尤为', '最少'}:
        value = -1.0
    elif text in EMPHASIS or text in {'比例', '的比例'}:
        value = -0.6
    elif text in {'所有', '所有的', '最'}:
        value = -0.3
    elif text and set(text) == {'·'} and len(text) > 1:
        value = -1.02
    return (doc, text, unfinished), 0.5 * value

