"""Component layers.1.mlp.down_proj:5530: a "nearly / resembles" word detector.

What it does, in plain terms: this output direction of layer 1's MLP goes strongly
negative on the Chinese words for "almost / nearly" (几乎, 差不多, 近乎, 接近, 将近)
and for "similar / resembling / like" (类似, 相似, 似, 诸如, 宛如, 疑似). It is weaker on
a few emphasis words (甚至, 尤其, 尤为, 简直, 最为). The 伦 family (伦, 倫, 伦理, 沦)
and 纯 are also negative, though they do not share that meaning. Everywhere else it
is near zero, apart from its first token of a document: there it is positive on code
keywords (package, import, const, void, ...) and single capital letters, and slightly
negative on digits. The values are rough per-word averages measured on training text.
"""

READS: tuple[str, ...] = ()

# "Almost / nearly" and "similar / resembling": the strong, consistent responders.
NEARLY_OR_SIMILAR = {
    "几乎": -4.2, "幾乎": -3.6, "近乎": -3.1, "差不多": -2.2, "几乎所有": -2.0,
    "几乎是": -1.6, "将近": -0.5, "类似": -4.2, "类似于": -3.0, "类似的": -2.5,
    "似": -1.2, "似的": -1.6, "疑似": -0.9, "接近": -1.1, "相似": -0.5, "宛如": -0.5,
    "不像": -1.5, "诸如": -2.1, "同类": -0.5, "之类": -0.4,
}
# Emphasis words that respond more weakly.
INTENSIFIERS = {"甚至": -0.5, "尤其": -0.8, "尤为": -1.6, "简直": -0.9, "最为": -0.7}
# The 伦 family and 纯: strongly negative, though not a clear shared meaning.
LUN_FAMILY = {"伦": -3.1, "倫": -4.4, "伦理": -2.6, "沦": -1.4, "纯": -0.9}
# First token of a document (no context before it).
DOC_START_CODE = {
    "package": 1.0, "import": 0.8, "const": 1.2, "function": 1.2, "void": 2.2,
    "int": 1.1, "//": 0.8, "<?": 0.7, "\\": 1.0,
}
DOC_START_UPPER = 0.5  # a single capital letter, such as a variable name
DOC_START_DIGIT = -0.2

WORDS = {**NEARLY_OR_SIMILAR, **INTENSIFIERS, **LUN_FAMILY}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        if token in DOC_START_CODE:
            return carry, DOC_START_CODE[token]
        if len(token) == 1 and token.isascii() and token.isupper():
            return carry, DOC_START_UPPER
        if token.isdigit():
            return carry, DOC_START_DIGIT
    return carry, float(WORDS.get(token, 0.0))

programs.sol:
"""A sparse model of nominal phrases, especially after Chinese 的.

Person/thing heads give positive values; another determiner, a count, or a
continuing modifier gives negative values. Several amplitudes distinguish
token-internal 的 from a preceding token ending in 的. A few Japanese
constructions and the <filename> metadata tag are recognized separately.
Unrecognized text gives zero. Ordinary Chinese personal pronouns have a small
negative baseline. State resets at document boundaries.
"""
import re
from functools import lru_cache
import cedict
import unicodedata

READS = ()
PRONOUNS = set('我你您他她它') | {
    '我们', '我們', '你们', '你們', '他们', '他們', '她们', '她們'
}


@lru_cache(maxsize=2048)
def classifier(word):
    return any(g.startswith(('classifier ', '(classifier'))
               for g in cedict.glosses(word))


def chinese(word, joined):
    if word in PRONOUNS:
        return 3.6
    if word == '自己':
        return 2.2
    if word == '人':
        return 1.6 if joined else 2.4
    # Generic things and utterances (shi / hua).
    if word in {'事', '话', '話'}:
        return 1.05 if joined else 2.4
    if word in {'东西', '東西', '事情', '朋友'}:
        return 0.55 if joined else 0.8
    if word in {'最', '最新', '最好'}:
        return -2.2
    # Continuously, step by step, one by one, further.
    if word in {'不断', '不斷', '逐步', '逐一', '进一步', '進一步'}:
        return -2.3
    if word == '一':
        return -0.36 if joined else -0.65
    count = re.fullmatch(r'[一二三四五六七八九十两兩几幾]+(.+)', word)
    if count and classifier(count.group(1)):
        return -0.95 if joined else -1.4
    if word in {'个', '個', '份', '名'}:
        return 0.2 if joined else -0.65
    if word.startswith(('这', '這', '那', '每', '任何', '哪些', '某些',
                        '许多', '許多', '其他', '另一', '各个', '各個')):
        return -0.4 if joined else -1.7
    if word in {'同时', '同時'}:
        return 0.85 if joined else 2.2
    if word in {'时', '時', '当天', '當天'}:
        return -2.3
    if word in {'前', '后', '後', '上', '下', '中', '内', '內', '外'}:
        return -0.85 if not joined else 0.0
    if word in {'、', '和'}:
        return 0.9
    if word in {'，', ','}:
        return 0.18
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    prev = carry[1] if same_doc else ''
    counting = carry[2] if same_doc else False
    s = unicodedata.normalize('NFKC', prefix.token_strings[-1])
    joined = s.startswith('的') and len(s) > 1
    if joined or prev.endswith('的'):
        value = chinese(s[1:] if joined else s, joined)
    elif counting and classifier(s):
        value = -0.65
    elif s in PRONOUNS:
        value = -0.12
    elif s in {'こと', 'もの'}:
        value = 0.9 if prev.endswith(('な', 'いう')) else 0.25
    elif s == 'か' and prev.endswith('という'):
        value = -1.3
    elif prev.endswith('の'):
        if s in {'人', '人は', '人が', '人に', '人の'}:
            value = 0.8
        elif s == 'では':
            value = -0.9
        elif s == 'に':
            value = 0.2
        elif s == 'を' or (len(s) == 1 and
                            unicodedata.name(s, '').startswith('HIRAGANA LETTER')):
            value = -0.6
        else:
            value = 0.0
    elif s == 'のに':
        value = 0.6
    elif s == 'filename' and prev == '<':
        value = 2.25
    elif s == '人' and prev.endswith(('些', '种', '種', '一般', '部分',
                                      '当地', '其他', '身边', '身邊',
                                      '多少', '有钱', '有錢', '党', '黨')):
        value = 0.6
    else:
        value = 0.0
    # A numeral after 的 licenses a measure word on the next step.
    word = s[1:] if joined else s
    counting = (joined or prev.endswith('的')) and word.isnumeric()
    return (doc, s, counting), value

programs.haiku:
"""Candidate 3: inside a noun phrase modified by 的 (X的NP):
the token right after 的 that opens the NP (demonstrative, quantifier, classifier) is negative;
the head noun or pronoun that completes it (person or thing) is positive.
Document starts get small class offsets (digits, spaces, punctuation up; CJK down)."""
READS = ()
OPENERS = {"这", "這", "那", "哪", "哪些", "这个", "這個", "那个", "那些", "这些", "一", "一个", "一些", "一种",
           "一次", "一样", "每", "每一", "许多", "全部", "最", "最好", "最新", "初步", "几", "两个", "有关",
           "名", "处", "次", "颗", "座", "个", "种", "件", "些", "不"}
HEADS = {"人", "你", "我们", "他", "她", "他们", "大家", "朋友", "话", "钱", "东西", "事", "心", "歌", "值",
         "水", "肉", "书", "面", "死", "情", "信", "命"}
def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    n = len(prefix.token_strings)
    prev = prefix.token_strings[-2] if n > 1 else ""
    if n == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        c = cur.strip()
        if c.isdigit():
            return None, 0.15
        if not c:
            return None, 0.12
        if '一' <= c[0] <= '鿿':
            return None, -0.1
        return None, 0.0
    if cur in ("的人", "的话", "的話", "的钱", "的事", "的东西", "的朋友"):
        return None, 1.5
    if cur.startswith("的") and cur[1:] in OPENERS:
        return None, -1.2
    if prev.endswith("的"):
        if cur in OPENERS:
            return None, -1.5
        if cur in HEADS:
            return None, 2.0
    return None, 0.0

programs.sol:
"""A partial detector for repeated I-like letters and numeral fragments.

I/I joins, Roman-numeral continuations and Cyrillic И/И joins are positive.
Repeated ones respond more strongly near section signs. Archaic v-for-u
spellings of und, unto and upon are negative. Small rules also cover repeated
punctuation and document starts: capitalization, articles/copulas, isolated
lowercase minim letters, and the unusually strong initial number 12.

Most weak token-specific and unusual negative word-fragment responses are
left at zero. State resets at document boundaries. This is only a partial
approximation, not a reconstruction of all the component's behavior.
"""
READS = ()
ROMAN = frozenset('IVXLCDM')
ARTICLES = frozenset({'a', 'an', 'the'})
COPULA = frozenset({'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'})
# Prefixes of the historical spellings vnd, vnto, and vpon.
OLD_U_PREFIXES = frozenset({'vnd', 'vnt', 'vpon'})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, prev, ones, first, recent = 0, '', 0, token, ''
    else:
        _, pos, prev, ones, first, recent = carry
    value = 0.0
    word = token.strip()
    if pos == 0:
        value = -0.13
        if token.startswith(' ') and word.isalpha():
            value -= 0.14
        if word[:1].isupper():
            value += 0.13
        if len(word) == 1 and word.isupper():
            value += 0.23
        if word in ARTICLES or word in COPULA:
            value = -0.60
        if token in {'i', 'l', 'm', 'n'}:
            value = -0.60
        if token == 'I':
            value = 0.73
        if word.isascii() and word.isdigit():
            value += 0.16
    else:
        previous = prev.rstrip()
        if token.startswith('I') and previous.endswith('I'):
            value += 1.66
        if token.startswith(('i', 'v', 'V')) and previous.endswith('I'):
            value += 0.8
        if token.startswith('I') and previous.endswith('i'):
            value += 0.8
        if previous.endswith('II') and token[:1].isalpha():
            value += 1.37
        if (token and set(token) <= ROMAN and previous
                and set(previous.strip().upper()) <= ROMAN
                and previous[-1] != 'I' and 'I' in token):
            value += 0.6
        if token == 'ii' and previous.endswith('i'):
            value += 1.2
        if token == 'И' and previous.endswith('И'):
            value += 1.8
        if token == '1' and ones:
            value += -0.055 if ones == 1 else 0.16
            if '§' in recent:
                value += 0.26 if ones == 1 else 0.54
        if token == prev and token and set(token) == {'·'}:
            value += 0.92
        if prev.strip() == 'v' and 'v' + token in OLD_U_PREFIXES:
            value -= 1.5
        if token == prev == '\r' and pos < 6:
            value -= 1.08
    if pos == 1 and first == '1' and token == '2':
        value = 2.79
    elif pos == 2 and first == '1' and prev == '2' and token == '2':
        value = 1.01
    ones = ones + 1 if token == '1' else 0
    return (doc, pos + 1, token, ones, first, (recent + token)[-100:]), value

"""Approximate a document-onset pulse and small identifier-number suffixes.

Training activations concentrate on document-initial tokens, especially source
file headers. There, familiar syntax, word classes, case, script and English
word frequency estimate the pulse's size. Elsewhere only an ASCII digit right
after an ASCII letter gets a small positive response. Most token-specific and
contextual variations are deliberately left unexplained.
"""
import math
import regex
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

PREPOSITIONS = set(('of to in for on with at from by into over under between '
                    'through about against without within across during until '
                    'before after around').split())
FUNCTION_WORDS = set(('and or but if while because although unless whether '
                      'as than so that the a an this these those some any '
                      'each every all both no another such').split())
PRONOUNS = set(('i you he she it we they me him her us them my your his '
                'its our their who what which whose').split())


@lru_cache(maxsize=16384)
def onset(token):
    s = token.strip()
    bare = not token[:1].isspace()
    if s == '<|im_start|>':
        return 3.23
    if s == '<|endoftext|>':
        return 13.4
    if s.isdigit():
        return -0.5
    if not s:
        if '\n' in token:
            return 5.2
        if token == ' ':
            return 3.5
        return min(9.5, 5.9 + 1.1 * math.log2(max(1, len(token))))
    # Unindented source-file preambles and declarations.
    if bare:
        if s == 'import':
            return 32.8
        if s in {'package', 'from'}:
            return 22.0
        if s in {'using', 'namespace', 'require', 'use'}:
            return 17.0
        if s in {'const', 'var', 'let'}:
            return 19.0
        if s in {'def', 'function', 'func', 'fn'}:
            return 15.0
        if s in {'class', 'struct', 'enum', 'interface', 'typedef',
                 'public', 'private', 'protected', 'void', 'int', 'char',
                 'module', 'string'}:
            return 12.5
        if s.startswith(('/*', '//')):
            return 3.4 if s == '//' and '\n' in token else 20.0
        if s.startswith(('"""', "'''")):
            return 16.0
        if s == '<':
            return 17.0
    if s.startswith('#!'):
        return 16.7
    if set(s) == {'#'}:
        return (18.66 if bare else 8.4) / math.sqrt(len(s))
    if s.startswith(('#include', '#define', '#if', '#pragma')):
        return 13.0
    if s == '<?':
        return 10.7
    if s == 'I':
        return 4.0
    if s == 'a':
        return 2.9 if not bare else 2.2
    if s in {'return', 'new', 'try', 'if', 'for', 'while', 'switch'}:
        return 10.0 if bare else 7.5
    if bare and s in {'print', 'select', 'SELECT', 'create', 'CREATE',
                      'export', 'type', 'cd'}:
        return 12.0
    if bare and s in {'Show', 'Give', 'Write', 'Find', 'Explain', 'Use'}:
        return 8.0
    if s == '.':
        return 2.2 if '\n' in token else (5.3 if bare else 10.0)
    if s in {'"', "'", '“', '”', '‘', '’'}:
        return 6.5
    if s == ',':
        return 4.3
    if s == '--':
        return 12.0 if bare else 5.0
    if s == ';':
        return 7.7 if bare else 5.0
    # Whole words and fragments: frequency, length, script and capitalization.
    if s.isalpha() and not s.isascii():
        if regex.search(r'\p{sc=Han}|\p{sc=Hiragana}|\p{sc=Katakana}', s):
            return 1.8
        if regex.search(r'\p{sc=Cyrillic}|\p{sc=Arabic}', s):
            return 0.0
        return 1.0
    if len(s) == 1 and s.isupper():
        return 0.3
    if s.isalpha():
        low = s.lower()
        if low == 'to':  # preposition and infinitive introducer
            return 8.6
        if low in PREPOSITIONS:
            return 5.5
        if len(s) > 1 and low in FUNCTION_WORDS:
            return 4.8
        if low in PRONOUNS:
            return 3.4
        z = zipf_frequency(low, 'en')
        value = (0.8 if bare else 0.2) + 0.12 * min(len(s), 15)
        value += 0.66 * max(0.0, z - 2.0)
        if z >= 4:
            value -= 0.5
        if s.istitle():
            value -= 0.3
        if s.isupper():
            value -= 1.9
        if len(s) <= 3 and z < 4:
            value -= 0.7
        return value
    if '\ufffd' in s:
        return 0.0
    if '\\' in s:  # escaped formatting and string fragments
        return 1.5
    if all(not c.isalnum() for c in s):
        return 5.0
    return 1.5


def identifier_suffix(token, previous):
    if len(token) != 1 or token not in '0123456789':
        return 0.0
    if not previous or not previous[-1].isascii() or not previous[-1].isalpha():
        return 0.0
    digit = int(token)
    value = 0.3 if digit == 0 else max(0.0, 0.95 - 0.25 * digit)
    if not previous[:1].isspace():
        value *= 0.65
    if previous[-1].isupper():
        value *= 0.4
    if previous.startswith('[') and previous[-1].isupper():
        value = 0.9  # numbered compiler diagnostic
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry != doc
    token = prefix.token_strings[-1]
    if first:
        value = onset(token)
    else:
        value = identifier_suffix(token, prefix.token_strings[-2])
    return doc, value

programs.haiku:
"""Document-opening token detector.

The component is silent inside a document and speaks only at a document's first token
(the token right after <|endoftext|>, or the first token of a row). There its size depends
on what the document opens with, a property of the opening token itself:
  - very strong when it opens a code or markup file, a comment or a preprocessor line
    (import, package, #, //, /*, const, using, from, #include ...);
  - moderate for other code keywords, for punctuation and for indentation whitespace;
  - mild for ordinary English words;
  - about zero for single letters, digits and non-Latin text.
Everywhere else in a document it stays at about zero.
"""

READS = ()

# Openers of source files, comments and preprocessor lines.
STRONG_WORDS = frozenset("import package const from using namespace include".split())
STRONG_MARKS = ("#", "//", "/*", "<?", "<!--", "<script", '"""', "'''")
# Other code keywords.
CODE_WORDS = frozenset(
    "def function class let var public private interface module require export declare "
    "struct return print try type select create int void bool static new".split()
)
ENGLISH = frozenset(
    "the a an of and to in is that for it with as on be by this are or at from not but "
    "i he she we you they his her their its if so".split()
)


def step(carry, prefix, upstream):
    if prefix.position > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        return carry, 0.0
    tok = prefix.token_strings[-1]
    word = tok.strip()
    if word in STRONG_WORDS or word.startswith(STRONG_MARKS):
        value = 20.0
    elif word in CODE_WORDS:
        value = 12.0
    elif not word:
        value = 6.0
    elif word.lower() in ENGLISH:
        value = 4.5
    elif not tok.isascii():
        value = 1.0
    elif word.isdigit() or (len(word) == 1 and word.isalnum()):
        value = 0.0
    elif not word.isalnum():
        value = 5.0
    else:
        value = 2.0
    return carry, value

programs.sol:
"""A small recognizer for source-file openings and structural text markers.

The strongest positives are include guards, file headers and first type
declarations, not ordinary prose uses of their words. Documentation, tests,
diffs and tracebacks have smaller signed cues. Forum anchors and dot leaders
are negative. Everything else is zero. The state is reset between documents;
it remembers a bounded text tail, the source language, and declarations seen.
"""
import re

READS = ()
MODIFIERS = r'(?:(?:public|private|protected|internal|static|abstract|final|partial|export)\s+)*'
DECLARATION = re.compile(r'\s*(?:\d+\t\s*)?' + MODIFIERS + r'$')


def predict(carry, token, document):
    if carry is None or carry[0] != document:
        carry = (document, '', '', False, 0, 0)
    _, text, language, declared, guards, includes = carry
    line = text.rsplit('\n', 1)[-1]
    word = token.strip()
    before = line + token[:len(token) - len(token.lstrip())]
    numbered = bool(re.match(r'\s*\d+\t', line))
    value = 0.0

    # Document markers, including a forum's link back to an individual post.
    if word and len(word) >= 2 and set(word) == {'·'}:
        value = -2.06
    elif word == 'permalink' and text.endswith('[#'):
        value = -6.1
    elif token == ':' and text == 'Title':
        value = 11.93
    elif word == ':' and re.fullmatch(r'---\n\w+', text):
        value = 1.7
    elif word == 'finished' and line.endswith('[Command'):
        value = -0.24
    elif (word == '"' and re.search(r'"type":\s*$', line)
          and '"description":' in text[-1500:]):
        value = -0.25
    elif word in {'PASS', 'FAIL'} and re.search(r'---\s*$', line):
        value = 0.37 if word == 'PASS' else 1.54
    elif word == ':' and re.search(r'--- (?:PASS|FAIL)$', line):
        value = 0.46 if line.endswith('PASS') else 0.89
    elif word == 'Test' and re.search(r'--- (?:PASS|FAIL):\s*$', line):
        value = 0.14 if 'PASS:' in line else 0.29
    elif word == 'parameter' and text.endswith('Required'):
        value = -2.6
    elif word == 'ATION' and text.endswith('OBSERV'):
        value = -0.32

    # C-family file headers and interpreter declarations.
    elif word == '#ifndef' and guards == 0:
        value = 7.0 if not text else (3.6 if len(text) < 10 else 8.7)
    elif word == '#define' and guards == 1:
        guard = re.search(r'#ifndef\s+(\w+)\s*$', text)
        if guard:
            value = 17.4 if re.search(r'_H_?$', guard[1]) else 8.0
    elif word == 'once' and re.search(r'#pragma\s*$', text):
        value = 17.55 if text == '#pragma' else 10.7
    elif word in {'//', '/*'} and re.search(r'#endif[ \t]*$', text):
        value = 8.0 if word == '//' else 4.4
    elif word in {'"', '<'} and re.search(r'#include\s*$', text):
        first = includes == 1 and not guards and 'pragma once' not in text
        value = (3.8 if first else 1.3) if word == '"' else (0.95 if first else 0.4)
        if '```' in text and first and word == '"':
            value = 1.4
    elif word == '#include' and includes == 0 and re.search(r'\*/\s*$', text):
        value = 1.9
    elif word == 'php' and text.endswith('<?'):
        value = 4.49 if text == '<?' else 0.9
    elif word in {'/env', '/bash'} and '#!' in line:
        value = 3.6 if text.startswith('#!') else 1.2
    elif word in {'python', 'python3', 'bash', 'sh', 'perl', 'ruby'} and '#!' in line:
        value = 2.5 if text.startswith('#!') else 0.15
    elif word == 'strict' and text in {"'use", '"use'}:
        value = 1.77
    elif token == '//\n' and not text:
        value = 7.1
    elif token.isspace() and text == '//\n//':
        value = 5.1

    # Type declarations are strongest before the first class body in a file.
    elif word in {'class', 'interface', 'struct', 'enum'} and DECLARATION.fullmatch(before):
        value = 0.08 if declared else 0.35
        if not declared and word in {'class', 'interface'}:
            value = {'java': 3.2, 'csharp': 5.1, 'php': 5.6,
                     'ruby': 3.3, 'cpp': 0.6}.get(language, 0.35)
            if word == 'interface' and language == 'java':
                value = 5.5
            if numbered:
                value *= 0.6
        declared = True
    elif word in {'public', 'internal'} and not before.strip():
        value = 0.16
        if not declared:
            value = {'java': 1.8, 'csharp': 3.2}.get(language, 0.16)
    elif word == '{' and language == 'csharp' and re.search(r'namespace[^{};]+\s*$', text):
        value = 2.1
    elif word == 'import':
        value = 0.65 if not text else -0.22
    elif word in {'def', 'func', 'function', 'void', 'fn'}:
        value = {'def': 0.25, 'func': 0.35, 'void': 0.35,
                 'function': 0.55 if language == 'php' else 0.06,
                 'fn': 1.4 if '#[test]' in text[-100:] else 0.5}[word]
    elif word == 'Test' and re.search(r'func\s*$', line):
        value = 1.5
    elif word == 'test' and text.endswith('#['):
        value = 1.5
    elif word in {'init', 'file'} and text.endswith('__'):
        value = 0.85 if word == 'file' else 0.42

    # Documentation and source-file metadata.
    elif word == '/**':
