    elif word == 'File' and re.fullmatch(r'\*\*\s*', line):
        value = 2.7
    elif word.startswith(':') and re.search(r'(?:File description|\*[^\n]*@\w+)\s*$', line):
        value = 2.0
    elif word == 'Id' and line.endswith('$') and '*' in line:
        value = 3.5
    elif word == ':' and line.endswith('$Id'):
        value = 6.8
    elif word == 'The' and 'Copyright' in line and re.search(r'\d{4}\s*$', line):
        value = 3.8
    elif word == 'All' and 'Copyright' in text[-300:]:
        value = 1.8
    elif (word.lower() in {'contains', 'defines'}
          and re.search(r'[Tt]his (?:file|module)\s*$', line)):
        value = 4.1
    elif word in {'brief', 'file', 'author', 'desc'} and text.endswith(('\\', '@')):
        value = {'author': 0.5, 'desc': 1.8}.get(word, 1.4)

    # Diff headers and Python/JavaScript stack frames.
    elif word == '--' and re.search(r'(?:^|\n)diff\s*$', text):
        value = 1.4
    elif word == 'git' and line.endswith('diff --'):
        value = 1.07
    elif word == 'at' and not line.strip() and token.startswith(' '):
        value = -0.4
