            language = 'cpp' if includes or guards else 'csharp'
        elif word == 'php' and text.endswith('<?'):
            language = 'php'
        elif word == 'module' and not before.strip():
            language = 'ruby'
    guards += word == '#ifndef'
    includes += word == '#include'
    if token == '<|endoftext|>':
        return (document, '', '', False, 0, 0), value
    return (document, (text + token)[-2000:], language, declared, guards, includes), value


def step(carry, prefix, upstream):
    return predict(carry, prefix.token_strings[-1], prefix.document_ids[-1])

"""Pulse on a document's opening token, lasting through exact repetitions.

The pulse is larger for letters than for numbers, punctuation or whitespace.
Title case and writing system refine its amplitude. After the initial uniform
run ends, predict zero: this deliberately omits small continuation fluctuations
and individual words' idiosyncratic opening amplitudes.
