import regex

READS = ()


def opening_pulse(token):
    text = token.strip()
    if not text:
        if '\n' in token or '\r' in token:
            return 3.25
        return 3.85 if '\t' in token else 2.6
    if token.startswith('<|'):
        return 4.2 if token == '<|endoftext|>' else 7.87
    if '\ufffd' in token:
        return 3.2
    if text.isdigit():
        return 4.15
    if not any(c.isalpha() for c in text):
        return 3.55
    if regex.search(r'\p{Han}|\p{Hiragana}|\p{Katakana}', text):
        return 4.25
    if not text.isascii():
        return 5.6
    if text[0].isupper() and not text.isupper():
        return 7.17
    return 6.2 if text.isupper() else 6.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_pulse(prefix.token_strings[-1])
        return (doc, token_id, value), value
    if token_id == carry[1]:
        return carry, carry[2]
    return (doc, None, 0.0), 0.0

