CYRILLIC = re.compile(r'в(?:од|ед|ест|ел|ож|ез|оз)')
LATIN = re.compile(r'(?:v[oe]d|w(?:od|ód|ied)|prowad)')
# Common Slavic verbal prefixes, including those in 'voivode'.
PREFIXES = {
    '', 'u', 'do', 'du', 'pri', 'pro', 'od', 'za', 'vy', 'pre', 'nad',
    's', 'roz', 'na', 'po', 'z', 'v', 'w', 'przy', 'prze', 'wy',
    'vo', 'voi', 'voivo', 'woje', 'voje',
