        carry = (doc, '', 0.)
    _, previous, last_value = carry
    token = prefix.token_strings[-1].lower()
    text = previous + token
    cut = len(previous)
    word = token.strip()
    value = 0.

    for match in CYRILLIC.finditer(text):
        if match.end() <= cut:
            continue
        root = match.group()
        before = LETTERS.search(text[:match.start()]).group()
        # Investment/known/news words are not the verb 'to lead'.
        if root == 'вест' and before in {'ин', 'из', 'не', 'но'}:
            continue
        if match.start() < cut:
            if len(word) <= match.end() - cut + 1:
                value = 4. if root == 'вел' else 6.
            else:
                value = 0.
        elif word == root:
            if token[0].isspace():
                value = 2.
            else:
                value = 10. if root == 'вод' else 6.
        elif word.startswith('производ'):
            value = 2.
        elif root == 'вел':
            value = 4.
        elif word.endswith(root):
            value = 5.
        else:
            value = 1.
        if root == 'вел' and 'увелич' in text:
            value = 0.
        if root in {'воз', 'вез'}:
            value *= 0.2
        # In-, across-, together-, and out- forms have stronger stem signals.
        if root in {'вод', 'вед', 'вест'}:
            if match.start() < cut or word == root:
                if before in {'в', 'пере', 'с'}:
                    value = 10.
                elif before == 'вы':
                    value = 8.

    for match in LATIN.finditer(text):
        if match.end() <= cut:
            continue
        before = LETTERS.search(text[:match.start()]).group()
        before = ''.join(c for c in unicodedata.normalize('NFD', before)
                         if not unicodedata.combining(c))
        if before in PREFIXES:
            if match.start() < cut:
                value = 4.
            elif word == match.group():
                value = 4.5
            else:
                value = 0.

    if '導' in token:
        value = 4. / max(1, len(word))
    strength = value
    if not value and previous and token:
        if token[0] in 'аеёиоуыэюяaeiouáéíóúýěů入':
