        value = 2.
    tail = LETTERS.search(text).group()[-40:]
    return (doc, tail, strength), float(value)

"""A spelling-fragment contrast, not a general past-tense detector.

Poetic 'd after a non-pronoun and a separate d after an English stem ending in
'e' are strongly negative. Short ed fragments are weakly negative when they
complete English verbs, but positive in non-English text or after a short
capitalized name fragment. Non-past-tense bed is strongly positive.
Word-frequency comparisons identify non-English context. Cyrillic ед endings
get smaller positives; verb-stem + éd gets a negative. Paired middle dots
and document-initial 12/122 have separate negative responses. Other tokens
are predicted zero; state resets at each document boundary.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
PRONOUNS = frozenset("""i you he she it we they there this that who what where
how why when which someone somebody anyone anybody everyone everybody nobody
something anything everything nothing one""".split())


@lru_cache(maxsize=32768)
def verb(word):
    return 'verb' in wordnet.parts_of_speech(word.lower())


@lru_cache(maxsize=32768)
def known_word(word):
    return bool(wordnet.parts_of_speech(word.lower()))


LANGUAGES = ('en', 'de', 'nl', 'it', 'fr', 'es', 'pl', 'cs', 'sv', 'nb')


@lru_cache(maxsize=32768)
def frequencies(word):
    return tuple(zipf_frequency(word.lower(), lang) for lang in LANGUAGES)


def foreign_context(text):
    words = re.findall(r'[^\W\d_]+', text)
    if text[-1:].isalpha():
        words = words[:-1]  # do not use the unfinished current word
    words = [w for w in words[-12:] if len(w) > 1]
    if len(words) < 3:
        return False
    scores = [sum(frequencies(w)[i] for w in words) / len(words)
              for i in range(len(LANGUAGES))]
    return max(scores[1:]) > max(3.0, scores[0] + 0.3)


def step(carry, prefix, upstream):
