        value = -3.5
    elif token.endswith('ед') and len(token.strip()) <= 3:
        value = 0.45 if token == 'ед' else 0.25
    if token == '··':
        value = -1.23
    if position == 1 and first == '1' and token == '2':
        value = -7.08
    if position == 2 and first == '1' and previous == token == '2':
        value = -2.58
    if position == 0:
        first = token
    state = (doc, joined, position + 1, first, token,
             (context + token)[-256:])
    return state, value

