Negative rules cover indexing and relation words, Python error names,
deprecation warnings, GUI events and lifecycle callbacks. Other rules cover
strict equality, text alignment, completion messages and opening headers.
Repeated middle dots and 'time period' have positive predictions. The same
suffix can score differently with a different preceding identifier.

Only the last 80 characters are retained, resetting at document boundaries.
Most text gets zero; many isolated lexical responses remain unexplained.
"""
import builtins
import re

READS = ()
PYTHON_ERRORS = tuple(
    name for name, cls in vars(builtins).items()
    if name.endswith('Error') and isinstance(cls, type)
    and issubclass(cls, BaseException)
)
LOCATION_CUES = {'value', 'point', 'vertex', 'angle', 'file', 'block',
                 'located', 'recorded', 'resource'}
COLLECTION_ACTIONS = {'find', 'select', 'delete', 'remove', 'replace',
                      'match', 'contain', 'contains', 'containing', 'hold',
                      'store', 'convert', 'check', 'expand', 'refresh'}
STATEMENTS = {'select', 'switch', 'print', 'break', 'continue', 'return',
              'sql', 'import', 'catch', 'match'}


def predict(s, tail, pos):
    words = re.findall(r'[A-Za-z_]+', tail)
