        return -7.29
    if s == 'php' and pos == 1 and tail == '<?':
        return -1.73
    if len(s) > 1 and set(s) == {'·'} and (not tail or tail.endswith(s)):
        return 1.09
    if s == ' ===':
        return -0.50
    if s == '-align' and tail.endswith('text'):
        return -1.76
    if s == ' finished' and before == 'command':
        return -0.98
    if s in {' at', ' At'}:
        if before in {'item', 'element', 'object'}:
            return -2.1
        return -0.65 if before in LOCATION_CUES else -0.075
    if s == 'At' and joined:
        return -5.1 if before.endswith(('value', 'char')) else -0.8
    if s == '_at':
        return -1.0
    if joined and s == 'Error':
        name = (words[-1] if words else '') + s
        return -1.5 if name.endswith(PYTHON_ERRORS) else -0.4
    if joined and s == 'Warning':
        return -2.2 if before.endswith('deprecation') else -0.6
    if (s in {'up', 'down', 'Up', 'Down'}
            and before.endswith(('mouse', 'key'))):
        return -4.8
    if joined:
        if s == 'Did' and before.endswith('component'):
            return -4.37
        if s in {'Mount', 'Update'} and before.endswith('did'):
            return -3.79
        if s == 'Event':
            if before.endswith(('pointer', 'keyboard', 'mouse')):
                return -3.3
            if before.endswith(('dispatch', 'execute', 'action', 'move')):
                return -1.3
            return 0.0
        if s in {'Click', 'Clicked'}:
            if before.endswith(('on', 'row', 'button', 'mouse')):
                return -2.3
            return -0.8
        if s in {'Change', 'Changed'}:
            if before.endswith(('property', 'item', 'visibility', 'index', 'state')):
                return -3.7
            return -2.2 if before.endswith('on') else -0.5
        if s == 'Mount':
            return -2.7
        if s == 'End':
            return -3.16 if before.endswith('pad') else -1.45
        if s in {'Start', 'Update', 'Updated'}:
            return -0.7
        if s in {'All', 'Of', 'As', 'By', 'Before', 'After'}:
            return {'All': -1.35, 'Of': -0.85, 'As': -0.8,
                    'By': -0.45, 'Before': -1.6, 'After': -0.45}[s]
    if s == '_all':
        return -1.1
    if s == '_of' and before in {'size', 'align', 'index'}:
        return -1.7
    if s == ' all' and before in COLLECTION_ACTIONS:
        return -0.7
    if s == ' of' and before in {'index', 'indexes', 'offset'}:
        return -0.7
    if s in {' exist', ' exists'} and before == 'not':
        return -0.65
    if s == ' statement' and before in STATEMENTS:
        return -1.65
    if s == ' period' and before == 'time':
        return 1.05
    if s == 'LOG' and before == 'change':
        return -1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, pos = '', 0
    else:
        _, tail, pos = carry
    s = prefix.token_strings[-1]
    value = predict(s, tail, pos)
    return (doc, (tail + s)[-80:], pos + 1), value

