"""Layer-1 MLP output feature 5544 (down_proj), a document-opening detector.

In plain terms: this component is silent almost everywhere (typical size about 0.03).
Its large responses happen at the first word of a document, the token right after
<|endoftext|> or at the very start of a row. There it responds to what kind of text
opens the document:
  - "using" (as in a C# "using System;" header) gives a strong positive response;
  - "1" followed by "2" as the first two tokens gives the largest response;
  - question words, articles and greetings ("What", "Is", "The", "Hello") give a
    moderate negative response;
  - code openers ("def", "print", "const", "#pragma", "function") give a stronger
    negative response;
  - comment or include openers ("#include", "/*", "//") give a mild positive one.
Everywhere else it predicts 0. Position inside the document is counted from the
document start, which resets where the document id changes (or at the row start).
"""

READS = ()

USING = {"using"}
COMMENT_OPENERS = {"#include", "/*", "//"}
QUESTION_OR_OPENER = {
    "What", "Which", "Who", "How", "Why", "Where", "When", "Is", "Are", "Do", "Does",
    "If", "There", "The", "In", "On", "After", "Yes", "No", "Hello", "Show", "Give",
    "Generate", "A", "An", "Welcome", "Title", "O",
}
CODE_OPENERS = {
    "def", "print", "const", "import", "int", "#ifndef", "#pragma", "function",
    "class", "return", "var", "let", "static",
}


def step(carry, prefix, upstream):
    t = prefix.position
    tok = prefix.token_strings[t].strip()
    same_doc = carry is not None and prefix.document_ids[t] == prefix.document_ids[t - 1]
    k = carry + 1 if same_doc else 0  # tokens since this document started
    value = 0.0
    if k == 0:
        if tok in USING:
            value = 1.6
        elif tok in CODE_OPENERS:
            value = -0.8
        elif tok in QUESTION_OR_OPENER:
            value = -0.35
        elif tok in COMMENT_OPENERS:
            value = 0.3
    elif k == 1 and prefix.token_strings[t - 1].strip() == "1" and tok == "2":
        value = 1.85
    return k, float(value)

