FOR = {
    'expression': 6.0, 'formula': 3.9, 'equation': 2.6,
    'solve': 3.6, 'calculation': 2.7, 'computation': 2.5,
    'compute': 2.3, 'calculate': 1.0, 'estimate': 1.3,
    'approximation': 1.5, 'value': 0.8, 'relation': 2.8,
    'recurrence': 4.5, 'identity': 2.8, 'solution': 0.5,
    'function': 0.5, 'form': 1.4, 'table': 0.6,
}
OF = {
    'calculation': 2.5, 'computation': 3.8, 'value': 0.82,
    'definition': 1.1, 'table': 1.2, 'estimate': 0.7,
    'approximation': 0.9, 'derivation': 1.0, 'proof': 0.5,
    'determination': 0.7, 'dependence': 0.7, 'form': 0.35,
    'measure': 0.4, 'measurement': 0.4, 'formula': 0.6,
    'sum': -0.26, 'number': -0.11, 'product': -0.17,
