    if 100 <= n < 190:
        strength += -0.23 + 0.52 * max(0, min(1, (n - 115) / 40))
    elif 210 <= n < 400:
        strength += 0.13
    elif n >= 400:
        strength += 0.08
    if n and n != 200 and n % 100 == 0:
