READS = ()


def year_pulse(year):
    decade = year // 10 * 10
    if 1500 <= year < 1750:
        value = 0.6
    elif 1750 <= year < 1800:
        value = 1.3
    elif 1800 <= year < 1900:
        value = 1.7 + 0.004 * (decade - 1800)
    elif 1900 <= year < 1970:
        value = 2.05 + 0.026 * (decade - 1900)
    elif 1970 <= year < 2020:
        value = 4.1
    elif 2020 <= year < 2040:
        value = 3.4 - 0.1 * (decade - 2020)
    elif 2040 <= year < 2100:
        value = 1.1
    else:
        return 0.0
    return value * (0.45 if year % 100 == 0 else 1.0)


