ADVERBS = {'then': .08, 'easily': .31, 'readily': .11,
           'successfully': .29, 'automatically': -.07,
           'previously': .16, 'subsequently': .03, 'later': .04, 'when': .09}
MODAL_BE = {'can': .46, 'could': -.04, 'may': -.13, 'might': -.26,
            'must': 0., 'should': .09, 'shall': .29, 'will': .02,
            'would': -.12, 'to': .12, 'not': .06, 'never': .12}
PASSIVE = re.compile(
    r'\b(?:is|are|was|were|be|been|being)\s+'
    r'(?:(?:not|then|also|now|often|usually|already|just|recently)\s+){0,2}'
    r'(?:\w+ed|known|given|taken|done|seen|shown|born|made|found|written)\b')

def predict(token, text):
    w = token.strip().lower()
    auxiliaries = FINITE | {'be', 'been', 'being'}
    if w not in auxiliaries | ADVERBS.keys():
        return 0.
    if token[0].isalnum() and text and text[-1].isalnum():
        return 0.  # A word fragment, not the auxiliary.
    words = re.findall(r"[a-z]+(?:'[a-z]+)?|\d+|[^\w\s]", text.lower()[-160:])
    p = words[-1] if words else ''
    q = words[-2] if len(words) > 1 else ''
    if w in ADVERBS:
        return ADVERBS[w] + (.65 if p in auxiliaries else 0.)
    if w == 'am':
        return -.22 if p == 'i' else 0.
    history = min(2, len(PASSIVE.findall(text.lower())))
    value = history * (.17 if w in {'been', 'being'} else
                       .10 if w == 'be' else .11)
    if w == 'be':
        if p in {'then', 'easily', 'readily', 'successfully', 'subsequently',
                 'automatically', 'later', 'now'}:
            value += .76
            p, q = q, words[-3] if len(words) > 2 else ''
        elif p in {'also', 'only', 'still'}:
            p, q = q, words[-3] if len(words) > 2 else ''
        if p in {"can't", 'cannot'}:
            p = 'can'
        value += MODAL_BE.get(p, .02)
        if p == 'to':
            if q in FINITE:
                value += .88
            if q in {'need', 'needs', 'needed', 'have', 'has', 'had',
                     'required', 'requires'}:
                value += .45
            if q == 'ready':
                value += .48
            if q in {'going', 'seems', 'seem', 'appears', 'appear', 'want',
                     'wants', 'wanted', 'expected', 'supposed',
                     'found', 'likely', 'out'}:
                value -= .41
        if p in {'not', 'never'}:
            for modal in words[-3:-1]:
                if modal in {'could', 'should', 'will'}:
                    value += .20
                elif modal in {'may', 'might'}:
                    value -= .23
        return value
    if w == 'been':
        value += .67 + {'has': .29, 'have': .16, 'had': .07,
                        'not': .33, 'always': -.39}.get(p, 0.)
        if PERSON.intersection(words[-4:]):
            value -= .35
        if {'would', 'could', 'might', 'may', 'must', 'should'} & set(words[-4:]):
            value -= .47
        return value
    if w == 'being':
        value += .43
        if p in FINITE:
            value += 1.51
        elif (p in {'not', 'now', 'currently', 'already', 'still',
                    'also', 'just', 'all'} and q in FINITE):
            value += .61
        if p in {'human', 'well', '-'}:
            value -= .10
        if p in {'of', 'to', 'about', 'for', 'as', 'without', 'by'}:
            value -= .28
        if p in {'after', 'before', 'from'}:
            value += .62
        return value

    # Personal subjects, existential 'there', and definitions favor copulas.
    past = w in {'was', 'were'}
    value += {'is': -.01, 'are': .15, 'was': .54, 'were': .78}[w]
    subject_groups = [
        (PERSON - {'it', 'they'}, -.28, -.48),
        ({'it', 'they'}, -.10, -.31),
        ({'there', 'here'}, -.20, -.49),
        ({'this', 'that', 'these', 'those'}, -.17, -.26),
        ({'which', 'what', 'who', 'how', 'where', 'when', 'why'},
         -.18, -.31),
        (DEFINITION, -.12, -.01),
    ]
    for group, present_offset, past_offset in subject_groups:
        if p in group:
            value += past_offset if past else present_offset
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, text)
    return (doc, (text + token)[-400:]), float(value)

"""Recognize chat-role and web-page boundary labels, rather than prose content.

The largest common pulse marks the assistant role.  Other pulses approximate
repeated page furniture: comment headings, curriculum labels, forum counters,
and bibliography boundaries. Tool markers and a few typographic structures
receive smaller fixed values. Ordinary text has a near-zero baseline.
Only the last 128 characters are retained; each document starts afresh.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    value = 0.001
    if previous == '<|im_start|>' and token == 'assistant':
        value = 0.75
    elif token == '<tool_call>':
        value = 0.136
    elif token == '<tool_response>':
        value = -0.125
    elif token == '</think>':
        value = 0.131
    elif len(token.strip()) > 1 and set(token.strip()) == {'·'}:
        value = 0.467
    elif token in ('---\n', '---\n\n'):
        value = -1.47 if token.endswith('\n\n') else -0.70
    elif token == '{' and re.search(r'\\(?:begin|end)$', tail):
        value = 0.32
    elif token == 'permalink':
        value = 0.93
    elif token == ' Tags' and tail.endswith('Show'):
        value = 1.02
    elif token == ' links' and tail.endswith('External'):
        value = -0.92
    elif token.isspace() and '\n' in token:
        line = tail.rsplit('\n', 1)[-1].strip()
        if line == 'References':
            value = -0.57
        elif (line in ('Views', 'Replies')
              or re.search(r'Replies\n[0-9,.]+[Kk]?$', tail)):
            value = -1.20
        elif line == 'Worksheet':
            value = -0.66
    elif token == ' Standards' and re.search(r'\d(?:st|nd|rd|th)$', tail):
        value = 5.29
    elif token == ' Level' and tail.endswith('Challenge'):
        value = 1.61
    elif token == ' Homework' and tail.endswith('assignment'):
        value = 3.67
    elif token == 'Worksheet' and tail.endswith('Math\n'):
        value = 2.07
    elif token == ' Plan' and tail.endswith('Lesson'):
        value = 0.60
    elif token == '\\$' and re.search(
            r'(?:Types:|Report this Resource)\s*$', tail):
        value = 2.2
    elif token == ' “' and re.search(r'(?:thoughts on|response to)$', tail):
        value = 4.06
    elif token == ' on' and tail.endswith('thoughts'):
        value = 0.86
    elif token == ' .\n\n' and re.search(r'posted by(?: on)?$', tail):
        value = 1.89
    return (doc, token, (tail + token)[-128:]), value

"""A spelling-sensitive 'din/in' detector, with a few phrase responses.

The largest negative rules recognize cardinal/ordinal and d+in (also d+yn)
fragments.  Grin, grind and German drinn fragments have positive rules.
'Early/late in' is negative; the assistant role label is positive.
These are approximate, token-boundary-sensitive rules, not a semantic parser.
The carry keeps only the latest alphabetic word fragment and resets per document.
"""
import re

READS = ()
IN_FRAGMENT = re.compile(
    r'[iy]n(?:[aeio]|al[s]?|a[s]?|e[ds]?|en|s|ate|n(?:er|en|ing|ed)?)?\Z'
)


def response(token, before):
    word = token.strip()
    low = word.lower()
    prev = before.lower()
    attached = bool(token[:1].isalpha())
    if token == 'assistant' and before == '<|im_start|>':
        return 1.05
    if low.startswith('cardinal'):
        return -4.4 if word[:1].isupper() else -7.1
    if low.startswith('ordinal'):
        return -5.2
    joined = (prev if attached else '') + low
    cut = len(joined) - len(low)
    if any(m.end() > cut for m in
           re.finditer(r'серед[иі]н|кардин', joined)):
        return -7.1
    if low == 'in' and prev in ('early', 'late'):
        return -4.4
    if low == 'in' and prev == 'earlier':
        return -1.25
    if low == 'numbers':
        if prev == 'cardinal':
            return -5.1
        if prev == 'large':
            return -2.6
    if low == 'data' and prev in ('big', 'large'):
        return -1.0
    if re.fullmatch(r'grin(?:ned|ning)?', low):
        return 3.7
    if attached and token == 'ale' and prev.endswith('cardin'):
        return -5.1
    if attached and low.startswith('ind') and prev.endswith('gr'):
        return 3.0 if low == 'ind' else 1.0
    if attached and IN_FRAGMENT.fullmatch(low) and (
            token.islower() or before.isupper()):
        if prev.endswith('card'):
            return -7.1
        if prev.endswith('ord') and low == 'inal':
            return -7.1
        if prev.endswith('gr'):
            if low.startswith('inn') or (low == 'in' and prev in ('gr','chagr')):
                return 6.6
            return 1.0
        if prev.endswith('dr') and low.startswith('inn'):
            return 5.7
        if prev.endswith('d') and not prev.endswith('std'):
            if low.startswith('inn'):
                return 3.7 if low == 'inner' else -1.0
            if low in ('inal','inate'):
                return -1.0
            if prev.endswith('dd'):
                return -5.7
            if prev.endswith('nd') and not prev.endswith(('und','ind')):
                return -0.7
            if low in ('ini','ino','ined'):
                return -2.0
            return -3.3
        if prev.endswith(('br','pr','tr','cr')):
            return -1.5 if low == 'inal' else 0.9
        if prev.endswith('r') and low.startswith('ina'):
            return -1.4
    if low.startswith('ин') and attached and prev.endswith('д'):
        return -2.4
    if re.search(r'din[aeio]?[ns]?\Z|дин[аы]?\Z', low):
        if low.endswith('stdin') or low.startswith(('coordin','един')):
            return 0.0
        if low.startswith('ordin'):
            return -0.7
        return -1.0 if token[:1].isspace() else -2.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, before)
    if token == '<|im_start|>':
        after = token
    else:
        match = re.search(r'[^\W\d_]+\Z', before + token)
        after = match.group()[-40:] if match else ''
    return (doc, after), value

"""A first-token lexical contrast, strongest on source-code openings.

Only the first visible token of each document gets a substantial prediction.
C/C++ directives, comments, module headers and declarations give positive
values; ordinary word and number openings tend to be mildly negative.
This deliberately ignores the much smaller, context-dependent later values.
"""
READS = ()

MODULE_WORDS = {
    'import', 'from', 'require', 'using', 'package', 'namespace', 'module',
    'def', 'function', '(function',
}
DECLARATIONS = {
    'const', 'var', 'class', 'struct', 'enum', 'public', 'static',
    'extern', 'typedef', 'local', 'global', 'my', 'object',
}


def opening_value(s):
    w = s.strip()
    if s.startswith('<|'):
        return 6.1 if s == '<|endoftext|>' else 0.0
    # File-opening C/C++ directives.
    if w in {'#if', '#ifdef', '#ifndef'}:
        return 23.0
    if w in {'#include', '#import'}:
        return 13.5
    if w in {'#define', '#pragma', '#region'}:
        return 17.5
    if w in {'#endif', '#else', '#undef', '#error', '#line'}:
        return 10.5
    # Comment, script, module and declaration openings.
    if w.startswith('/*'):
        return 9.7
    if w.startswith('//'):
        if len(w) >= 4:
            return 13.0
        return 11.2 if s == '//' else 6.5
    if w.startswith('#!'):
        return 6.8
    if w.startswith('#'):
        return 4.1
    if s == 'export':
        return 19.0
    if s in MODULE_WORDS:
        return 6.3
    if s in DECLARATIONS:
        return 8.5
    if w in {'@interface', '@class'}:
        return 17.0
    if w.startswith(('<?', '<!')):
        return 5.9
    if w.startswith(('"""', "'''")):
        return 6.0
    if w == "'use":
        return 8.6
    if w.startswith('__'):
        return 8.0
    # Coarse baselines for other kinds of initial token.
    if '\n' in s or '\r' in s:
        return 2.0
    if s.isspace():
        return -1.1
    if w.isascii() and w.isdigit():
        return -0.5 if w in {'0', '1'} else -1.5
    if w in {'"', "'", '“', '”'}:
        return -1.3 if s[0].isspace() else -3.5
    if w.startswith(('\\n', '\\t')):
        return -9.3 if w.startswith('\\t') else -4.8
    if w.isascii() and any(c.isalpha() for c in w):
        if s[0].isspace():
            return -0.3
        if w.isupper() and len(w) > 1:
            return 0.2
        if w.istitle() and len(w) > 3:
            return -1.0
        return -1.1 if len(w) == 1 and w.islower() else -0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry != doc
    return doc, opening_value(prefix.token_strings[-1]) if first else 0.0

