"""layers.1.mlp.down_proj:5567 -- a "document-opening token" component.

Its activation is almost entirely set at the first token of each document (the
first token after a document break in a packed row). There the attention can only
see the token itself, so the value is a fixed, token-dependent number. Elsewhere
the component is essentially silent (|activation| is about 0.05).

This program predicts, at a document's first token, a value from the kind of token
it is:
  * code / comment / preprocessor openers (#include, #ifndef, //, /*, @interface)
    -> strongly positive (about +7);
  * code keywords that open a file (package, using, export, import, ...) -> about +5;
  * SQL keywords (SELECT, FROM, WITH, ...) -> negative (about -0.9);
  * digits -> about -1.1;
  * prepositions, articles and other function words -> about -0.6;
  * any other word or fragment -> about -0.3.
Every other position predicts 0.
"""

import re

READS = ()

CODE_OPENERS = ("#", "//", "/*", "@", "<?", "///")
CODE_KEYWORDS = {
    "package", "using", "import", "include", "export", "define", "class", "interface",
    "public", "private", "static", "void", "return", "def", "func", "fn", "let", "var",
    "const", "namespace", "module", "require", "template",
}
SQL_KEYWORDS = {
    "select", "from", "where", "insert", "into", "join", "with", "update", "delete",
    "and", "or", "order", "group", "values", "set", "inner", "left", "table",
}
FUNCTION_WORDS = {
    "of", "to", "for", "at", "in", "on", "with", "from", "by", "and", "or", "is", "are",
    "the", "a", "an", "that", "this", "as", "be", "it",
}


def opening_value(token: str) -> float:
    """Activation the component takes on a document's first token."""
    bare = token.strip().lower()
    if token.startswith(CODE_OPENERS):
        return 7.0
    if bare in CODE_KEYWORDS:
        return 5.0
    if bare in SQL_KEYWORDS:
        return -0.9
    if bare.isdigit():
        return -1.1
    if bare in FUNCTION_WORDS:
        return -0.6
    return -0.3


def step(carry, prefix, upstream):
    """Called at each token; carry is unused. A token starts a document if it is the
    row's first token or its document id differs from the previous token's."""
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return carry, 0.0
    return carry, opening_value(prefix.token_strings[-1])
